const de:TranslationMap={
"joyagoo-fee-policy-free-agent-service-transaction-costs":{title:"Joyagoo-Gebührenregel: kostenloser Agentenservice und zahlbare Kosten",description:"Trenne den kostenlosen Kernservice von Verkäufer-, Zahlungs-, Rückgabe-, Zusatz- und Paketkosten.",meta:"GEBÜHRENPOLITIK · 15 MIN",sourceNote:"Geltungsbereich am 29. August 2026 anhand aktueller öffentlicher Joyagoo-Hinweise geprüft; Live-Checkout und aktuelle Regel entscheiden.",quickFacts:["Kostenlos meint den Kernkaufservice","Ware und Verkäuferfracht bleiben zahlbar","Optionen können kosten","Rückgaben können Abzüge erzeugen","Internationale Fracht ist getrennt"],rows:[
["Mit der genauen Aussage beginnen","Joyagoo bezeichnet den Einkaufsagenten-Service öffentlich als kostenlos. Eng gelesen bedeutet dies keinen separaten Kernservice-Aufschlag im beschriebenen Standardablauf.¶Es bedeutet nicht, dass Produkt, Zahlungsweg, Nachverkauf oder internationales Paket kostenlos sind. Der Umfang muss im selben Satz sichtbar bleiben."],
["Jeden Betrag einer Partei zuordnen","Produkt und chinesische Inlandsfracht stammen aus dem Verkäufergeschäft; Zahlungsanbieter oder Bank können eigene Umrechnung anwenden.¶Notiere Bezeichnung, verantwortliche Partei, Stufe, Erstattbarkeit und Beleg. Nenne nicht jeden Checkout-Betrag automatisch Joyagoo-Servicegebühr."],
["Standardhilfe und Zusatzarbeit trennen","Kostenloser Kernservice macht nicht jede Lageranforderung kostenlos. Aktuelle Oberfläche entscheidet über Auswahl, Verfügbarkeit und angezeigten Betrag.¶Speichere Name, Betrag, Währung und Auftrag. Frage, welches konkrete Problem eine Zusatzoption löst und ob der Käufer sie aktiv ausgewählt hat."],
["Rückgaben als eigenen Kostenpfad behandeln","Rückfracht oder Bearbeitung kann abhängig von Grund, Verkäuferzustimmung, Zustand und Belegen abgezogen werden. Ein Zeitfenster ist keine kostenlose Rückgabe.¶Bewahre Option, Statuszeit, Fotos, Grund, Antwort, Fracht, Bearbeitung und Rückrechnung auf. Käuferwunsch und bestätigter Verkäuferfehler sind getrennte Fälle."],
["Internationalen Versand als zweite Transaktion lesen","Nach Lagerung wird internationale Fracht nach Ziel, Methode, Gewicht, Volumen und Paketdaten berechnet. Eine frühe Summe kann Schätzung oder Einzahlung sein.¶Speichere Paket, Ziel, Linie, Messdaten, Verpackung und Anpassung. Dies erklärt die Herkunft des Betrags, ohne eine dauerhafte Route oder Formel zu versprechen."],
["Währung und Zoll nicht falsch zuordnen","Unterschiede zwischen Anzeige, Autorisierung und Konto können Währung, Prozessor, Netzwerk, Bank oder Zeitpunkt betreffen. Ohne Checkout-Bezeichnung ist keine Joyagoo-Gebühr bewiesen.¶Zoll gehört ebenfalls nicht zur Kostenlos-Aussage. Zielregeln und tatsächlicher Import bestimmen mögliche Steuern, Abgaben und Bearbeitung."],
["Aussage vor Veröffentlichung oder Zahlung prüfen","Sichere aktuelle Regel, Datum und Wortlaut. Gruppiere Live-Beträge unter Ware, Inlandsfracht, Zahlung, Zusatz, Rückgabe, internationales Paket und Zoll.¶Kostenloser Agentenservice darf nur zusammen mit seinem Umfang stehen. Bei Widerspruch zwischen Regel und Bildschirm pausieren, beide Belege sichern und schriftlich klären."],
["Drei Transaktionsbeispiele prüfen","Ein Standardkauf kann kostenlosen Kernservice und zahlbare Ware zugleich zeigen. Eine gewählte Lageroption ist separat; eine Rückgabe mit zulässigem Abzug erzeugt rückwirkend keine Standardgebühr.¶Die Beispiele gelten nur mit ihren Bezeichnungen und Bedingungen. Unklassifizierte Beträge bleiben offen, bis aktuelle Regel oder Support sie erklärt."],
["Konflikte und Änderungen offenlegen","Öffentliche Seiten können geändert oder anders übersetzt sein und dem Live-Feld vorübergehend widersprechen. Sichere URL, Titel, Datum und Feld und beschreibe den Konflikt eng.¶Eine Supportantwort gehört zum betreffenden Vorgang und wird nicht automatisch globale Dauerregel. Transparente Unsicherheit ist besser als eine erfundene Prozentzahl."]]},
"joyagoo-buying-fees-guide":{
title:"Joyagoo Tabelle & Kaufleitfaden 2026: Links, Gebühren, QC und Versand",description:"Faktengeprüfter Joyagoo-Tabellenleitfaden zu Produktsuche, Live-Prüfung, Gebühren, Lager-QC, Rückgabe und internationalem Versand.",meta:"JOYAGOO TABELLE · 15 MIN",sourceNote:"Faktenbasis: offizielle Joyagoo-Leitfäden zu Suche, Einkauf, Gebühren und Bestellstatus. Live-Angebot und Checkout vor Zahlung prüfen.",quickFacts:["Tabellenlinks dienen der Entdeckung","Agentenservice als kostenlos gelistet","Produkt und China-Versand bleiben zahlbar","QC folgt nach Lagereingang","Internationaler Versand ist separat"],rows:[
["Mit dem richtigen Modell beginnen","Joyagoo ist Einkaufs- und Versandagent, nicht der Verkäufer jedes gelisteten Produkts. Produktkauf und internationaler Versand sind zwei getrennte Entscheidungen mit eigenen Zahlungen.¶Ein Spreadsheet dient nur zur Entdeckung. Bestand, Preis, Variante und Versandfähigkeit müssen auf der aktuellen Produktseite vor jeder Zahlung erneut geprüft werden."],
["Was kostenloser Agentenservice bedeutet","Die veröffentlichte Gebührenerklärung bezeichnet den Einkaufsservice als kostenlos. Warenpreis, chinesischer Inlandsversand, Rücksendung, internationale Fracht, Zoll und optionale Leistungen können trotzdem Kosten verursachen.¶Ein belastbares Budget trennt Waren, China-Kosten, Zusatzleistungen und internationalen Versand, statt das Wort kostenlos auf die gesamte Bestellung zu übertragen."],
["Bestellstatus als Kontrollpunkte nutzen","Zahlung ausstehend, Bearbeitung, gekauft, Verkäufer versendet, Lager eingetroffen, QC abgeschlossen, eingelagert und international versendet markieren unterschiedliche Verantwortungsbereiche.¶Notiere Status und Zeitpunkt. Eine Verzögerung beim Verkäufer verlangt eine andere Anfrage als fehlende Lagerprüfung oder ein ruhendes internationales Tracking."],
["Vor der Zahlung einen Listing-Nachweis anlegen","Speichere Verkäuferlink, ausgewählte Größe oder Farbe, Preis, Inlandsfracht, Größentabelle und wichtige Hinweise. Listings können nach dem Kauf geändert werden.¶Dieser Datensatz ist später der Maßstab für QC und Rückgabe. Ohne ihn lässt sich schwer beweisen, welche Variante tatsächlich bestellt wurde."],
["Verkäuferrisiko verstehen","Der ursprüngliche Verkäufer kontrolliert Bestand, Versandtempo, Listing-Genauigkeit und viele Rückgabebedingungen. Joyagoo kann unterstützen, aber keine fehlenden Verkäuferrechte erzeugen.¶Bevorzuge klar dokumentierte Angebote mit eindeutigen Optionen, Maßen und Bildern. Ein etwas höherer Preis kann weniger Risiko als ein unklarer Billig-Link bedeuten."],
["Was beim Lagereingang passiert","Nach Ankunft folgen Wareneingang, allgemeine Qualitätsprüfung, Fotos und Einlagerung. Standardfotos zeigen nicht automatisch jedes Maß, Innenetikett oder kleine Detail.¶Vergleiche zuerst Identität und Variante, dann Zustand. Fordere entscheidungsrelevante Winkel oder Maße sofort an, weil die Rückgabefrist an QC Completed gebunden ist."],
["Rückgabe ist zeitkritisch","Die veröffentlichte Richtlinie nennt für berechtigte Artikel 120 Stunden nach QC Completed. Verkäuferunterstützung, Zustand und Verpackung bleiben zusätzliche Voraussetzungen.¶Ohne anerkannten Qualitätsfehler trägt der Käufer meist die Rückfracht; zusätzlich nennt die Richtlinie etwa 0,75 USD Servicegebühr. Ein klarer Bildnachweis verbessert die Anfrage."],
["Lagerzeit ist Planungszeit","Joyagoo nennt 90 kostenlose Lagertage pro Artikel sowie eine kostenpflichtige Verlängerung. Unterschiedliche Ankunftstage erzeugen unterschiedliche Fristen.¶Setze ein eigenes Versanddatum deutlich vor der ältesten Frist. So bleiben Zeit für Austausch, Zusatzfoto, Routenvergleich und Verpackungsänderung."],
["Internationaler Versand ist die zweite Kaufentscheidung","Nach der Einlagerung werden Artikel, Ziel, Route und Verpackung für ein Paket gewählt. Produktbeschränkungen, Maße und Zielland beeinflussen die sichtbaren Linien.¶Der erste Betrag kann eine Schätzung sein und sich nach Packen oder Nachmessung ändern. Vergleiche Berechnung, Schutz und Einschränkungen statt nur den Startpreis."],
["Zoll und Versicherung getrennt prüfen","Empfänger tragen laut offizieller Zollinformation mögliche Steuern, Bußgelder und Rücksendungen. Eine Systemdeklaration garantiert keine Freigabe.¶Versicherung ist routen- und landabhängig. Speichere den aktuellen Deckungsumfang für Verlust, Schaden oder Beschlagnahme vor der Zahlung."],
["Checkout-Checkliste für Käufer","Vor Produktzahlung Link, Variante, Verkäuferhinweise und erwartete QC-Belege prüfen. Vor Ablauf der Rückgabefrist alle Fotos mit dem gespeicherten Listing vergleichen.¶Vor Paketzahlung Lagerfristen, Verpackung, Gewichtsregel, Deklaration, Versicherung, Adresse und aktuelle Routenbedingungen kontrollieren."]]},
"joyagoo-qc-return-window-guide":{
title:"Joyagoo QC-Fotos und 5-Tage-Rückgabe: Entscheidungsleitfaden",description:"QC-Fotos mit dem Listing vergleichen, sinnvolle Belege anfordern, Mängel dokumentieren und innerhalb der veröffentlichten 120 Stunden handeln.",meta:"QC & RÜCKGABE · 13 MIN",sourceNote:"Faktenbasis: Joyagoo Shopping Guidance, Rückgaberichtlinie, Serviceübersicht und Hinweise zum Paketempfang. Verkäuferregeln bleiben maßgeblich.",quickFacts:["QC folgt nach Lagereingang","Rückgabe: 120 Stunden","Verkäuferberechtigung zählt","Verpackung kann Rückgabe beeinflussen","Fotos müssen Entscheidungen klären"],rows:[
["QC ist Kontrollpunkt, keine Garantie","Die Lagerprüfung ist eine allgemeine Inspektion mit Fotos, keine vollständige Echtheits- oder Qualitätsgarantie. Käufer müssen entscheiden, ob die Bilder für ihre Anforderungen genügen.¶Frage nicht nur, ob der Artikel gut aussieht. Prüfe, ob die Fotos Identität, Variante, Maße und entscheidende Mängel belegen."],
["Referenz vor den Fotos vorbereiten","Speichere Listing, gewählte Option, Größentabelle, Zubehör und wichtige Produktdetails. Ohne Referenz kann nur das Aussehen, nicht die Übereinstimmung bewertet werden.¶Eine kurze Notiz pro Artikel erleichtert Zusatzfoto und Rückgabe und schützt gegen spätere Änderungen der Verkäuferseite."],
["Identität vor Verarbeitung prüfen","Beginne mit Produkttyp, Farbe, Modell, Größenetikett, Menge und Zubehör. Erst danach folgen Nähte, Oberflächen oder Symmetrie.¶Bei Unsicherheit ein klares Foto von Label, Code oder Maßband verlangen, statt aus Beleuchtung oder Perspektive zu raten."],
["Zustand in fester Reihenfolge kontrollieren","Prüfe Gesamtform, Vorder- und Rückseite, Verbindungen, Hardware, Oberflächen, Labels, Zubehör und Verpackung immer in derselben Reihenfolge.¶Trenne kleine kosmetische Abweichung von funktionalem Defekt und beziehe Preis, Nutzung und Rücksendekosten in die Entscheidung ein."],
["Entscheidungsrelevante Fotos verlangen","Zusatzbilder sind sinnvoll, wenn ihr Ergebnis Keep oder Return ändern kann: Maßband, Fleck, Gegenseite, Serien- oder Größenlabel sowie vollständiges Zubehör.¶Formuliere Ort und Zweck genau. Ein pauschales Mehr Fotos kann wertvolle Zeit verbrauchen, ohne die offene Frage zu klären."],
["Start der Rückgabefrist kennen","Die offizielle Richtlinie nennt fünf Tage beziehungsweise 120 Stunden ab Status QC Completed, nicht ab dem späteren Öffnen der Fotos.¶Notiere pro Artikel den Zeitstempel. Warte nicht auf andere Lagerartikel, weil Konsolidierung warten kann, die Verkäuferfrist aber nicht."],
["Berechtigung ist nicht automatisch","Die Frist gilt nur, wenn Verkäufer und Drittplattform die Rückgabe unterstützen und der Artikel verkaufsfähig sowie passend verpackt bleibt.¶Prüfe flexible Rückgaberegeln vor dem Kauf und vermeide irreversible Verpackungsänderungen vor der endgültigen Behalteentscheidung."],
["Kosten und Verantwortung verstehen","Ohne bestätigten Qualitätsfehler zahlt der Käufer meist die China-Rückfracht; die Richtlinie erwähnt rund 0,75 USD Servicegebühr. Bei anerkanntem Fehler kann Verkäuferverantwortung gelten.¶Vergleiche Rückerstattung, Fracht und Zeit. Ein falsches Maß oder defekter Reißverschluss wiegt anders als ein leicht entfernbarer Faden."],
["Eine bearbeitbare Rückgabe schreiben","Nenne Bestellnummer, gewählte Variante und den beobachtbaren Unterschied. Lege Listing-Nachweis und das passende Lagerfoto bei.¶Konkrete Angaben wie falsche Größe, Riss oder fehlendes Zubehör sind prüfbarer als allgemeine Unzufriedenheit oder unbelegte Behauptungen."],
["QC für fragile und formstabile Ware","Schuhe, Taschen, Brillen oder zerbrechliche Produkte brauchen zusätzliche Winkel, Formvergleich und Prüfung tragender Teile. Verpackungsschutz gehört zur Versandentscheidung.¶Ein Artikel kann im Lager intakt sein und durch zu schwache Verpackung später beschädigt werden. QC und Packanweisung müssen deshalb zusammenpassen."],
["Nach Zustellung weiter dokumentieren","Sichtbare Schäden möglichst mit dem Zusteller prüfen. Außenkarton, Label, Innenpolsterung, Rechnung und Produktbilder behalten, bevor etwas entsorgt wird.¶Joyagoo fordert schnelle Belege; Hinweise nennen zwei Arbeitstage bei später entdecktem Schaden und Kontakt innerhalb von 72 Stunden."],
["Das kompakte QC-System","Erstens Identität prüfen, zweitens entscheidende Qualitätsmerkmale, drittens fehlende Belege sofort anfordern, viertens Frist und Kosten berechnen.¶Zum Schluss Keep, Zusatzfoto, Austausch oder Rückgabe ausdrücklich dokumentieren. So wird QC zu einem wiederholbaren Prozess statt Bauchgefühl."]]},
"joyagoo-warehouse-rehearsal-shipping-guide":{
title:"Joyagoo Lager und Versand: 90 Tage, Probeverpackung und Konsolidierung",description:"Der vollständige Weg vom Lager zum Paket mit Fristen, Kombination, Verpackung, Routenauswahl, Frachtanpassung, Versicherung und Tracking.",meta:"LAGER & VERSAND · 15 MIN",sourceNote:"Faktenbasis: Shopping Guidance, Logistikübersicht, Hinweise zur Sammelsendung, Bestellstatus, Versicherung und Tracking.",quickFacts:["90 kostenlose Tage je Artikel","Probeverpackung 20 CNY","Routen nach Produkt geprüft","Gutscheine nicht stapelbar","Tracking kann verzögert sein"],rows:[
["Lager als Planungswerkzeug nutzen","Das Lager verbindet einzelne Verkäuferbestellungen mit dem internationalen Paket. Nutze diese Phase für QC, Rückgabe, Gruppierung und Routenvergleich.¶Eine Liste mit Ankunft, QC-Entscheidung, Rückgabefrist und Zielpaket verhindert, dass Artikel unbemerkt altern."],
["Die 90-Tage-Regel verstehen","Veröffentlicht sind 90 kostenlose Tage pro Produkt, nicht zwingend pro Gesamtbestellung. Später eintreffende Artikel haben andere Fristen.¶Setze eine frühere interne Grenze, damit Austausch, Zusatzfoto oder Zahlung noch ohne Eile möglich bleiben."],
["QC vor Konsolidierung abschließen","Nur bestätigte Artikel sollten in die endgültige Paketplanung. Eine Rückgabe nach irreversibler Verpackungsänderung kann schwieriger werden.¶Prüfe Identität, Zustand und gewünschte Verpackung, bevor mehrere Waren als eine Einheit behandelt werden."],
["Warum Konsolidierung Kosten senken kann","Mehrere Einzelpakete wiederholen häufig Erstgewicht und Bearbeitung. Eine gemeinsame Sendung kann diese Wiederholungen reduzieren.¶Größer ist aber nicht automatisch billiger: Volumengewicht, Größenlimits und Risikokonzentration können eine sinnvolle Teilung rechtfertigen."],
["Nach Verpackungsverträglichkeit gruppieren","Weiche Kleidung, formstabile Schuhe, zerbrechliche Ware und empfindliche Oberflächen brauchen unterschiedliche Behandlung. Ein starres Produkt kann die Außenmaße des ganzen Pakets bestimmen.¶Gruppiere nach Schutz und Form, nicht nur nach Ankunftsdatum. Zwei passende Pakete können besser als eine problematische Mischung sein."],
["Standardabgabe oder Probeverpackung","Bei Standardabgabe beginnt die Zahlung mit einer geschätzten Fracht und wird nach dem Packen angepasst. Probeverpackung ist mit 20 CNY gelistet und liefert vorher realistischere Maße.¶Der Service ist kein Rabatt. Er lohnt sich, wenn die Information Route, Teilung, Kartonentfernung oder Versandentscheidung verändern kann."],
["Packanweisungen je Artikel schreiben","Notiere genau, welche Verkaufsbox entfernt werden darf, welche Form geschützt werden muss und wo Verstärkung nötig ist. Allgemeine Wünsche können widersprüchliche Ergebnisse erzeugen.¶Jede Einsparung hat einen Tausch: weniger Box senkt Volumen, Verstärkung erhöht Gewicht, Vakuum kann empfindliche Formen beschädigen."],
["Routen erst mit bekanntem Paket lesen","Produktart, Ziel, Maße, Gewicht und Beschränkungen bestimmen die verfügbaren Linien. Eine frühere Preisübersicht ist keine Garantie für das fertige Paket.¶Vergleiche aktuelle Berechnungsregel, Grenzen, Versicherung und erwartete Übergaben, sobald realistische Paketdaten vorhanden sind."],
["Schätzung und tatsächliche Abrechnung trennen","Die erste Abrechnung basiert auf eingelagerten Werten und angenommener Verpackung. Nach dem Packen misst das Lager; der Logistikdienstleister kann erneut messen.¶Speichere Schätzung und Endwerte. Eine Differenz ist nicht automatisch Fehler, sollte aber mit Maßen, Gewicht, Formel und Rundung erklärbar sein."],
["Gutscheine im richtigen Schritt nutzen","Versandgutscheine gelten laut Anleitung nur für internationale Fracht und sind nicht stapelbar. Sie reduzieren nicht den Produktpreis.¶Bewerte den Gutschein erst nach Paket- und Routenwahl, damit ein Rabatt keine ungeeignete Linie attraktiver erscheinen lässt."],
["Versicherung und Zoll bleiben Routenfragen","Deckung für Verlust, Schaden oder Beschlagnahme hängt von Land, Linie und aktueller Entschädigungsregel ab. Zollfreigabe wird nicht garantiert.¶Prüfe Deklaration, Empfängerpflichten, Ausschlüsse und Nachweisbedingungen vor der Paketzahlung und speichere die aktuelle Regel."],
["Tracking und Zustellnachweis","Nach internationalem Versand erscheint Tracking im Paketbereich. Mehrere Übergaben können Scanpausen erzeugen, ohne automatisch Verlust zu bedeuten.¶Bei Schäden Außenverpackung, Label, Polsterung und Produkt dokumentieren und innerhalb der offiziellen Fristen melden."],
["Praktischer Lagerkalender","Tag null ist der jeweilige Lagereingang. QC und Rückgabe sofort bearbeiten, danach kompatible Gruppen bilden und eine interne Versandfrist setzen.¶Vor Paketabgabe Maße, Verpackungswünsche, Route, Versicherung, Deklaration, Adresse und verfügbaren Gutschein in einer letzten Prüfung bestätigen."]]},
"volumetric-weight-guide":{
title:"Joyagoo Istgewicht und Volumengewicht: die Paketmathematik",description:"Boxen messen, routenspezifische Teiler vergleichen und verstehen, warum leichte, sperrige Sendungen teurer als erwartet werden können.",meta:"VERSANDMATHEMATIK · 12 MIN",sourceNote:"Faktenbasis: Joyagoo-Leitfäden zu Ist- und Volumengewicht, Routentabelle, Schätzabrechnung und Shopping Guidance.",quickFacts:["Das höhere Gewicht kann zählen","Teiler unterscheiden sich","Verpackung zählt mit","Schätzung ist kein Angebot","Carrier kann nachmessen"],rows:[
["Gleiches Gewicht, unterschiedliche Kosten","Transport belegt Gewicht und Raum. Deshalb vergleichen einige Linien das Waagengewicht mit einem dimensionsbasierten Wert und berechnen den höheren.¶Die richtige Schätzung beginnt beim fertigen Karton, nicht bei der Summe nackter Produktgewichte."],
["Was Istgewicht enthält","Istgewicht umfasst Ware und verwendete Verpackung: Verkaufsbox, Schutz, Folie, Füllung und Außenkarton. Packwünsche verändern den Endwert.¶Entfernung spart Gewicht, kann aber Schutz kosten; Verstärkung erhöht Gewicht, kann jedoch einen teureren Schaden verhindern."],
["Berechnung des Volumengewichts","Veröffentlicht ist Länge × Breite × Höhe in Zentimetern geteilt durch einen Routen- oder Carrierteiler. Beispiele nennen 5000, 6000, 7000 und 8000.¶Es gibt keinen sicheren Universalteiler. Prüfe aktuelle Einheit, Schwelle, Rundung und Formel jeder sichtbaren Route."],
["Ein Rechenbeispiel","Ein Paket mit 50 × 40 × 30 cm hat 60.000 cm³. Geteilt durch 5000 sind das 12 kg, durch 6000 10 kg und durch 8000 7,5 kg.¶Wiegt es real 6 kg, kann je nach Route jeder dieser Volumenwerte die Abrechnung bestimmen."],
["Volumentreiber finden","Schuhkartons, Hüte, Daunenjacken, Schutzkoffer und halbvolle Verkäuferkartons bestimmen häufig eine oder mehrere Außenseiten.¶Finde heraus, welcher Artikel Länge, Breite und Höhe setzt. Dort bringt eine sinnvolle Packänderung den größten Effekt."],
["Routenschwellen verändern das Ergebnis","Manche Postlinien nutzen Volumen erst ab einer Seitenlänge, Expresslinien oft grundsätzlich, andere Linien verwenden Beuteltests oder eigene Divisoren.¶Vergleiche Gesamtkosten mit denselben realistischen Maßen, nicht nur Preis pro Kilogramm aus verschiedenen Tabellen."],
["Geschätztes Gewicht bleibt vorläufig","Das System schätzt Verpackung aus Lagerdaten. Entfernte Boxen, Verstärkung oder eine besondere Anordnung verändern das fertige Paket.¶Speichere die Schätzung, plane aber eine Spanne. Der physisch gepackte Gegenstand ist für die Abrechnung wichtiger."],
["Logistikdienstleister kann nachmessen","Nach der Lagermessung kann der Carrier das Gewicht bestätigen oder anpassen. Scanner, Rundung und gesetzte Verpackung können kleine Unterschiede erzeugen.¶Prüfe nach Versand die tatsächlichen Abrechnungsdetails, bevor du eine Abweichung als Fehler einstufst."],
["Wann 20 CNY Probeverpackung sinnvoll sind","Probeverpackung liefert vor der endgültigen Zahlung realistischere Maße und Fracht, ändert aber weder Formel noch Tarif.¶Sie ist besonders nützlich bei mehreren Boxen, gemischten Formen, Grenzwerten oder Routen, deren Reihenfolge von wenigen Zentimetern abhängt."],
["Ein besseres Versand-Spreadsheet","Erfasse Gewicht, unverzichtbare und entfernbare Verpackung, realistische Außenmaße sowie Formel jeder Kandidatenroute. Berechne Volumen separat.¶Kennzeichne Datum und Schätzstatus. Das Blatt soll Entscheidungen vergleichen, nicht eine unveränderliche Endsumme versprechen."],
["Verpackungsentscheidungen priorisieren","Zuerst Schutz sichern, dann nutzlose Verpackung entfernen, kompatible Ware platzsparend ordnen, sinnvolle Teilungen vergleichen und erst danach Routen rechnen.¶So wird kein billigerer Karton gebaut, der das wichtigere Ziel einer sicheren Zustellung verfehlt."],
["Letzte Gewichtskontrolle","Bestätige Maße, Istgewicht, Divisor, Schwelle, Rundung und höhere-Gewicht-Regel. Prüfe, ob die Anzeige noch Schätzung oder bereits Packwert ist.¶Speichere Packwünsche, Gutschein, Versicherung und Deklaration. Diese Belege erklären spätere Anpassungen."]]},
"joyagoo-reviews-buyer-signals":{
title:"Joyagoo Bewertungen: Lob, Kritik und was Käufer prüfen sollten",description:"Eine ausgewogene Auswertung, die offizielle Regeln von wiederkehrenden Käuferberichten zu Bestellung, QC, Support, Fracht, Verzögerung und Erstattung trennt.",meta:"KÄUFERBEWERTUNGEN · 13 MIN",sourceNote:"Community-Signale: öffentliche Trustpilot-Zusammenfassungen, App-Store-Bewertungen und Reddit-Diskussionen, geprüft im August 2026. Einzelberichte sind keine Garantie.",quickFacts:["Bewertungen sind Einzelfälle","Route und Land verändern Ergebnisse","Lob betrifft Bedienung und Hilfe","Kritik betrifft Kosten und Verzögerung","Offizielle Regeln bleiben Basis"],rows:[
["Eine Agentenbewertung richtig lesen","Eine Bewertung vermischt oft Verkäufer, Einkaufsagent, Carrier und Zoll. Ohne genannten Status lässt sich schwer erkennen, welche Partei das Ergebnis verursacht hat.¶Nutze Reviews, um Prüffragen zu finden, nicht um Lieferzeit, Produktqualität oder Zollausgang zu garantieren."],
["Was öffentliche Bewertungen loben","Positive Beiträge erwähnen häufig einfache Bestellung, hilfreiche Kommunikation, gute Produktzustände, sichere Verpackung und schneller als erwartete Lieferung.¶Diese Signale sind stärker, wenn Route, Ziel, Gewicht, Daten und Differenz zwischen Schätzung und Endpreis genannt werden."],
["Häufigste Warnung: Versandkosten","Negative Zusammenfassungen nennen unerwartet hohe Fracht oder Nachzahlungen. Das passt zum offiziellen Zweistufenmodell und zu möglichem Volumengewicht.¶Für eine faire Bewertung braucht man Startschätzung, Endmaße, entfernte Boxen, Divisor, Route und Carrier-Nachmessung."],
["Verzögerungen brauchen Status und Uhr","Langsame Verkäuferabgabe, Lagerprüfung, Paketberechnung, Carrier-Übernahme, Transfers und Zoll sind verschiedene Phasen. Drei Wochen ohne Start- und Endstatus sind wenig aussagekräftig.¶Vergleiche nur ähnliche Route und Destination und behandle Lieferzeit als Spanne mit möglichen Ausnahmen."],
["QC-Lob kann Verkäuferqualität meinen","Gute Verarbeitung entsteht beim ursprünglichen Verkäufer; Joyagoo liefert allgemeine Prüfung und Bilder. Ein positives Produktreview bewertet daher mehrere Beteiligte.¶Beiträge mit Verkäuferlink, QC-Fotos, Maßen und Zustellbildern sind nützlicher, garantieren aber keine nächste Charge."],
["Support direkt testen","Es gibt Lob für schnelle Hilfe und Kritik an Antwort- oder Erstattungsproblemen. Fallkomplexität, Zeitzone und genaue Anfrage beeinflussen das Ergebnis.¶Teste vor großer Bestellung eine konkrete Frage. Später immer Nummer, Status, Datum, gewünschte Aktion und Belege angeben."],
["Anreize und dünne Reviews beachten","Belohnte Beiträge sind nicht automatisch falsch, aber kurze Sternebewertungen ohne Daten haben wenig Entscheidungswert. Gleiches gilt für dramatische negative Titel ohne Beweise.¶Trenne nachweisbare Ereignisse, Behauptungen und zuständige Partei und prüfe Policy-Aussagen auf den aktuellen offiziellen Seiten."],
["App-Store-Wertungen beschreiben eher die Oberfläche","App-Bewertungen betreffen oft Suche, Checkout, Benachrichtigungen und Support. Sie sagen weniger über einen bestimmten internationalen Carrier oder Verkäufer aus.¶Trenne Softwarekomfort vom Paketergebnis; eine gute App garantiert weder günstige Route noch Zollfreigabe."],
["Qualitäts-Scorecard für Bewertungen","Höheres Gewicht erhalten Ziel, Daten, Paketmaße, Linie, Start- und Endfracht, QC-Zeit und Ausgang eines Claims. Reine Sterne oder Werbesprache erhalten weniger Gewicht.¶Prüfe außerdem, ob Verkäufer, Agent, Carrier und Zoll sauber voneinander getrennt werden."],
["Was Erstkäufer selbst testen können","Beginne mit einer kleinen, gut dokumentierten Bestellung. Beobachte Kauf, Verkäuferdispatch, Lagereingang, QC, Support, Frachtanpassung und Tracking.¶Nach Zustellung Datum, Kosten, Route, Scanpausen, Verpackung und Zustand erfassen. Die eigene Destination liefert relevantere Daten als ein globaler Durchschnitt."],
["Ausgewogenes Fazit","Öffentliche Bewertungen zeigen positive Signale bei Bedienung, Kommunikation, Verpackung und Lieferung, aber auch Sorgen bei Fracht, Verzögerung, falscher Ware und Lösung.¶Offizielle Regeln definieren Gebühren, Rückgabe, Lager, Gewicht und Versicherung; Community-Berichte zeigen, welche Punkte vor der Bestellung geprüft werden sollten."]]}
};

const es:TranslationMap={
"joyagoo-fee-policy-free-agent-service-transaction-costs":{title:"Política de tarifas Joyagoo: servicio gratuito y costes pagaderos",description:"Separa el servicio básico gratuito de costes del vendedor, pago, devolución, extras y paquete.",meta:"POLÍTICA DE TARIFAS · 15 MIN",sourceNote:"Alcance comprobado el 29 de agosto de 2026 en las guías públicas actuales; mandan la política y el checkout activos.",quickFacts:["Gratis describe el servicio básico","Producto y envío nacional se pagan","Los extras pueden cobrarse","Las devoluciones pueden deducir","El envío internacional es otra fase"],rows:[
["Empezar por la afirmación exacta","Joyagoo describe como gratuito el servicio del agente de compra. Leído con precisión, no hay un cargo separado por la asistencia básica del flujo publicado.¶No significa que producto, pago, posventa o paquete internacional sean gratuitos. El alcance debe acompañar siempre a la palabra gratis."],
["Asignar cada importe a su responsable","Producto y envío chino proceden de la operación del vendedor; procesador o banco pueden aplicar conversión aparte.¶Registra etiqueta, parte responsable, fase, condición de reembolso y prueba. No llames tarifa Joyagoo a toda cifra del checkout."],
["Separar asistencia estándar y trabajo opcional","La gratuidad básica no incluye automáticamente cada solicitud de almacén. Pantalla y política actuales determinan catálogo, disponibilidad y precio.¶Guarda nombre, importe, moneda y pedido. Comprueba qué problema resuelve la opción y si el comprador la seleccionó."],
["Tratar la devolución como otra rama","Flete de devolución o gestión pueden deducirse según motivo, aceptación del vendedor, condición y pruebas. Una ventana no equivale a devolución gratuita.¶Conserva opción, hora de estado, fotos, motivo, respuesta, transporte, gestión y cálculo de reembolso. Preferencia y error confirmado son casos distintos."],
["Leer el envío internacional como segunda transacción","Tras el almacén, el flete depende de destino, método, peso, volumen y paquete. Un importe inicial puede ser estimación o depósito.¶Guarda paquete, destino, línea, medidas, embalaje y ajuste. El objetivo es explicar la cifra sin prometer una ruta o fórmula permanente."],
["No atribuir mal moneda y aduana","Diferencias entre pantalla, autorización y extracto pueden ser moneda, procesador, red, banco o tiempo. Sin etiqueta del checkout no se prueba una tarifa Joyagoo.¶La aduana tampoco pertenece a la gratuidad. Las reglas del destino y la importación real controlan impuestos y gestión."],
["Auditar antes de publicar o pagar","Guarda regla, fecha y palabras actuales. Agrupa importes en mercancía, flete nacional, pago, extra, devolución, paquete internacional y aduana.¶Servicio gratuito solo se publica con su alcance. Si política y pantalla discrepan, pausa, guarda ambas y pide aclaración escrita."],
["Probar tres ejemplos de transacción","Una compra estándar puede combinar servicio básico gratuito y producto pagado. Una opción de almacén elegida es separada; una devolución con deducción no crea retroactivamente una tarifa estándar.¶Los ejemplos solo valen con etiquetas y condiciones. Deja sin clasificar cualquier importe hasta que política o soporte actual lo explique."],
["Revelar conflictos y cambios","Las páginas pueden cambiar, traducirse de modo distinto o discrepar temporalmente del campo activo. Guarda URL, título, fecha y etiqueta y describe el conflicto con precisión.¶Una respuesta de soporte pertenece a ese caso y no se vuelve norma global permanente. La incertidumbre transparente es mejor que un porcentaje inventado."]]},
"joyagoo-buying-fees-guide":{title:"Hoja Joyagoo y guía de compra 2026: enlaces, tarifas, control y envío",description:"Guía verificada de la hoja Joyagoo sobre descubrimiento, comprobación del anuncio, costes, control, devoluciones y envío internacional.",meta:"HOJA JOYAGOO · 15 MIN",sourceNote:"Base factual: guías oficiales de búsqueda, compra, tarifas y estados de Joyagoo. Comprueba el anuncio y el pago activos.",quickFacts:["Los enlaces sirven para descubrir","Servicio de agente anunciado como gratuito","Producto y envío chino se pagan","El control sigue a la llegada","El flete internacional va aparte"],rows:[
["Empieza con el modelo correcto","Joyagoo es un agente de compra y envío, no el vendedor original de cada artículo. La compra del producto y el paquete internacional son operaciones separadas.¶La hoja sirve para descubrir; stock, precio, variante y restricciones deben revisarse en la ficha activa antes de pagar."],
["Qué significa servicio gratuito","La explicación oficial indica que el servicio de agente es gratuito, pero siguen existiendo producto, entrega nacional, devolución, flete internacional, aduanas y extras.¶Un presupuesto útil separa mercancía, costes en China, servicios opcionales y envío mundial."],
["Usa los estados como puntos de control","Pago pendiente, procesando, comprado, vendedor enviado, llegado, control completado, almacenado y enviado internacionalmente representan etapas distintas.¶Guarda estado y fecha para dirigir cada consulta al vendedor, almacén, agente o transportista correcto."],
["Crea un registro antes del pago","Guarda enlace, opción, talla, color, precio, entrega nacional, tabla de medidas y notas. La publicación puede cambiar después.¶Ese registro será la referencia del control y una prueba concreta si el artículo recibido no coincide."],
["Comprende el riesgo del vendedor","El vendedor controla existencias, despacho, exactitud y muchas condiciones de devolución. El agente puede ayudar, pero no crear derechos inexistentes.¶Prioriza anuncios claros con opciones, medidas e imágenes coherentes aunque el precio no sea el mínimo."],
["Qué ocurre al llegar al almacén","Tras la llegada se registra, inspecciona de forma general, fotografía y almacena. Las fotos estándar no muestran automáticamente cada medida o etiqueta.¶Confirma primero identidad y opción, luego estado, y solicita de inmediato la evidencia que pueda cambiar la decisión."],
["La devolución tiene reloj","La política publicada marca 120 horas tras QC Completed para productos elegibles, además de condiciones de vendedor, estado y embalaje.¶Sin defecto aceptado, el comprador suele pagar el retorno y se menciona una tarifa aproximada de 0,75 USD."],
["El almacenamiento es tiempo de planificación","Joyagoo publica 90 días gratuitos por artículo y extensión de pago. Artículos con llegadas distintas tienen fechas distintas.¶Fija una fecha interna anterior para conservar margen de cambio, fotos extra, comparación de rutas y pago."],
["El envío internacional es otra compra","Cuando los artículos están guardados eliges contenido, destino, línea y embalaje. Restricciones, medidas y país cambian las rutas visibles.¶El primer importe puede ser estimado y ajustarse tras el embalaje o la medición del transportista."],
["Separa aduanas y seguro","El destinatario asume posibles impuestos, multas o devoluciones; una declaración del sistema no garantiza el despacho.¶El seguro depende de línea, país y norma vigente. Guarda cobertura y exclusiones antes de pagar."],
["Lista final del comprador","Antes de comprar confirma enlace, variante, vendedor y pruebas esperadas. Antes de 120 horas compara las fotos con el registro.¶Antes del paquete revisa plazos, embalaje, peso cobrable, declaración, seguro, dirección y reglas activas."]]},
"joyagoo-qc-return-window-guide":{title:"Fotos QC de Joyagoo y devolución en 5 días: guía para decidir",description:"Cómo comparar fotos con el anuncio, pedir pruebas útiles, documentar defectos y actuar dentro de las 120 horas publicadas.",meta:"CONTROL Y DEVOLUCIÓN · 13 MIN",sourceNote:"Base factual: guía de compra, política de devolución, descripción del servicio y avisos de recepción de Joyagoo.",quickFacts:["Control después de la llegada","Devolución: 120 horas","Importa la elegibilidad del vendedor","El embalaje influye","Las fotos deben resolver decisiones"],rows:[
["El control no es una garantía total","El almacén realiza una revisión general con fotografías; no es una autenticación ni una promesa de perfección.¶Pregunta si las imágenes demuestran identidad, variante, medidas y problemas que cambiarían conservar por devolver."],
["Prepara la referencia antes","Guarda anuncio, opción elegida, tabla de talla, accesorios y detalles esenciales. Sin referencia solo puedes valorar apariencia.¶Una nota por pedido facilita fotos adicionales y protege frente a cambios posteriores del vendedor."],
["Identidad antes que acabado","Comprueba producto, color, modelo, etiqueta de talla, cantidad y piezas incluidas antes de estudiar costuras o superficies.¶Si algo no está claro, pide etiqueta, código o medida exacta en vez de adivinar por luz o perspectiva."],
["Inspecciona siempre en el mismo orden","Revisa forma, frente, espalda, uniones, herrajes, superficie, etiquetas, accesorios y embalaje.¶Distingue variación cosmética de fallo funcional y valora precio, uso y coste de retorno."],
["Pide fotos que cambien la decisión","Una medida, primer plano de mancha, lado opuesto, etiqueta o accesorios completos son útiles cuando resuelven conservar o devolver.¶Describe ubicación y objetivo; pedir más fotos sin precisión puede gastar el plazo sin aclarar nada."],
["Conoce el inicio del plazo","Los cinco días o 120 horas empiezan cuando el estado pasa a QC Completed, no cuando el comprador abre después las imágenes.¶Registra cada hora límite y no esperes a que lleguen otros productos."],
["La elegibilidad no es automática","El vendedor y la plataforma deben admitir devolución; el artículo suele necesitar estado revendible y embalaje requerido.¶Comprueba flexibilidad antes de comprar y evita cambios irreversibles antes de decidir."],
["Costes y responsabilidad","Sin defecto confirmado el comprador suele pagar el envío de vuelta y la política cita unos 0,75 USD de servicio.¶Compara reembolso, flete y tiempo; una talla incorrecta no pesa igual que un hilo suelto."],
["Escribe una solicitud accionable","Indica pedido, variante y diferencia observable y adjunta la ficha guardada con la foto correspondiente.¶Talla equivocada, rotura o accesorio ausente son afirmaciones comprobables; una queja vaga no lo es."],
["Control de artículos frágiles","Calzado, bolsos, gafas y piezas rígidas necesitan ángulos, simetría y comprobación de elementos estructurales.¶Control y solicitud de embalaje deben diseñarse juntos para reducir daños posteriores."],
["Después de la entrega","Inspecciona daños visibles con el mensajero cuando sea posible y conserva caja, etiqueta, protección, factura e imágenes.¶Las guías piden pruebas rápidas: dos días laborables para daños descubiertos después y contacto dentro de 72 horas."],
["Sistema compacto de decisión","Primero identidad, después calidad decisiva, luego evidencia faltante y finalmente plazo y coste.¶Registra expresamente conservar, pedir foto, cambiar o devolver para convertir el control en un proceso repetible."]]},
"joyagoo-warehouse-rehearsal-shipping-guide":{title:"Almacén y envío Joyagoo: 90 días, ensayo y consolidación",description:"Del almacén al paquete: plazos, combinación, embalaje, rutas, ajustes de flete, seguro y seguimiento.",meta:"ALMACÉN Y ENVÍO · 15 MIN",sourceNote:"Base factual: guías oficiales de compra, logística, consolidación, estados, seguro y seguimiento.",quickFacts:["90 días gratis por artículo","Ensayo indicado en 20 CNY","Rutas filtradas por producto","Cupones no acumulables","El seguimiento puede tardar"],rows:[
["Usa el almacén para planificar","El almacén conecta pedidos de vendedores con el paquete internacional. Sirve para control, devolución, agrupación y comparación.¶Registra llegada, decisión, plazo y paquete previsto para que ningún artículo quede olvidado."],
["Entiende los 90 días","La guía publica 90 días gratuitos por producto, por lo que cada llegada puede tener una fecha distinta.¶Establece un límite anterior que deje tiempo para cambio, foto adicional y pago."],
["Termina el control antes de consolidar","Solo los artículos confirmados deben entrar en el plan final; algunos cambios de embalaje dificultan una devolución.¶Comprueba identidad, estado y protección antes de tratarlos como una unidad."],
["Por qué combinar puede ahorrar","Varios paquetes repiten primer tramo de peso y manipulación. Una caja común puede reducir repeticiones.¶Pero una caja mayor puede activar peso volumétrico, límites o más riesgo; compara también divisiones."],
["Agrupa por compatibilidad","Textiles blandos, zapatos, frágiles y superficies delicadas necesitan protección diferente; un objeto rígido fija dimensiones.¶Agrupa por forma y riesgo, no solo por fecha de llegada."],
["Envío estándar o ensayo","El envío estándar empieza con depósito estimado y ajuste posterior. El ensayo publicado por 20 CNY embala primero y ofrece medidas más realistas.¶No es descuento; vale cuando la información puede cambiar ruta, división o retirada de cajas."],
["Escribe instrucciones por artículo","Indica qué caja retirar, qué forma proteger y dónde reforzar. Solicitudes genéricas pueden producir resultados contradictorios.¶Menos caja reduce volumen; refuerzo añade peso; vacío puede dañar formas sensibles."],
["Lee las rutas con el paquete conocido","Producto, destino, peso, medidas y restricciones determinan líneas disponibles. Una tabla antigua no garantiza la ruta final.¶Compara fórmula, límites, seguro y transferencias con datos realistas del paquete."],
["Separa estimación y cobro real","El sistema estima con datos almacenados; después mide el almacén y el operador puede volver a medir.¶Guarda ambos valores y comprueba que diferencia, fórmula y redondeo sean explicables."],
["Usa cupones en el momento correcto","Los cupones solo se aplican al flete internacional y no se acumulan. No reducen el precio del producto.¶Valóralos después de elegir paquete y línea para no favorecer una ruta inadecuada."],
["Seguro y aduanas son decisiones de ruta","Cobertura, decomiso, pérdida o daño dependen del país y la línea; tampoco existe garantía aduanera.¶Revisa declaración, responsabilidades, exclusiones y pruebas antes del pago."],
["Seguimiento y prueba de entrega","Tras el despacho aparece tracking; los transbordos pueden generar pausas sin demostrar pérdida.¶Si hay daño, documenta exterior, etiqueta, protección y producto dentro del plazo oficial."],
["Calendario práctico","Día cero es la llegada de cada artículo. Resuelve control y devolución, forma grupos compatibles y fija fecha interna.¶Antes de enviar confirma medidas, embalaje, ruta, seguro, declaración, dirección y cupón."]]},
"volumetric-weight-guide":{title:"Peso real y volumétrico en Joyagoo: matemáticas del paquete",description:"Cómo medir cajas, comparar divisores por ruta y entender por qué un paquete ligero y grande puede costar más.",meta:"CÁLCULO DE ENVÍO · 12 MIN",sourceNote:"Base factual: guías de peso real y volumétrico, tabla de rutas, cobro estimado y guía de compra.",quickFacts:["Puede mandar el peso mayor","Los divisores cambian","El embalaje cuenta","La estimación no es precio final","El operador puede medir otra vez"],rows:[
["Mismo peso, coste distinto","El transporte consume peso y espacio; algunas líneas comparan báscula y cálculo dimensional y cobran el mayor.¶La estimación correcta parte de la caja terminada, no de los productos sin embalar."],
["Qué incluye el peso real","Incluye producto, caja comercial, protección, relleno y paquete exterior. Las solicitudes cambian el resultado.¶Retirar reduce peso pero protección; reforzar añade peso y puede evitar daños caros."],
["Cómo se calcula el volumen","La fórmula publicada es largo × ancho × alto en centímetros dividido por el divisor de la ruta. Se citan 5000, 6000, 7000 y 8000.¶No uses un divisor universal: confirma umbral, unidades y redondeo de cada línea."],
["Ejemplo práctico","Una caja de 50 × 40 × 30 cm tiene 60.000 cm³: son 12 kg con 5000, 10 con 6000 y 7,5 con 8000.¶Si la báscula marca 6 kg, el valor volumétrico puede gobernar en las tres rutas."],
["Encuentra los causantes de volumen","Cajas de zapatos, sombreros, chaquetas acolchadas y embalajes medio vacíos suelen fijar las dimensiones exteriores.¶Identifica qué objeto determina largo, ancho y alto antes de pedir cambios."],
["Los umbrales cambian la respuesta","Algunas líneas aplican volumen solo desde cierta longitud, otras siempre, y otras usan bolsa o divisores propios.¶Compara el total con las mismas medidas realistas, no tarifas aisladas por kilo."],
["El peso estimado es provisional","El sistema asume embalaje a partir del almacén; retirar cajas, reforzar o recolocar cambia el paquete real.¶Guarda una horquilla y recuerda que el objeto terminado domina el cobro."],
["El transportista puede volver a medir","El operador puede confirmar o ajustar lo medido por el almacén por escáner, redondeo o asentamiento.¶Consulta los detalles reales después del envío antes de clasificar la diferencia como error."],
["Cuándo compensa el ensayo de 20 CNY","Aporta medidas más realistas antes del pago, pero no cambia fórmula ni tarifa.¶Es útil con muchas cajas, formas mixtas, umbrales o rutas sensibles a pocos centímetros."],
["Una hoja de envío mejor","Registra peso, embalaje necesario y extraíble, dimensiones y fórmula de cada ruta, calculando volumen por separado.¶Añade fecha y estado estimado; la hoja compara decisiones, no promete una cifra fija."],
["Prioridad de embalaje","Protege primero, elimina después lo inútil, ordena compatibles, compara divisiones y finalmente calcula rutas.¶Así no ahorras volumen creando un paquete incapaz de llegar seguro."],
["Control final","Confirma medidas, peso real, divisor, umbral, redondeo y regla del mayor, además de si el valor sigue estimado.¶Guarda instrucciones, cupón, seguro y declaración para explicar ajustes."]]},
"joyagoo-reviews-buyer-signals":{title:"Opiniones sobre Joyagoo: elogios, dudas y qué verificar",description:"Análisis equilibrado que separa políticas oficiales de señales de compradores sobre pedidos, control, soporte, costes, retrasos y reclamaciones.",meta:"OPINIONES DE COMPRADORES · 13 MIN",sourceNote:"Señales públicas de Trustpilot, App Store y Reddit revisadas en agosto de 2026. Son experiencias individuales, no garantías.",quickFacts:["Las opiniones son anecdóticas","Ruta y país cambian el resultado","Se elogia facilidad y ayuda","Se critican costes y retrasos","Mandan las reglas oficiales"],rows:[
["Cómo leer una opinión de agente","Una reseña puede mezclar vendedor, agente, transportista y aduanas. Sin etapa concreta no identifica bien la causa.¶Úsala para descubrir preguntas, no para prometer calidad, plazo o despacho."],
["Qué suelen elogiar","Los comentarios positivos mencionan facilidad, comunicación, buen estado, embalaje seguro y entrega rápida.¶Pesan más cuando incluyen destino, ruta, peso, fechas y diferencia entre estimación y total."],
["Advertencia principal: el coste","También aparecen fletes inesperados o importes extra, coherentes con el pago separado y posible volumen.¶Para evaluarlo hacen falta estimación, medidas finales, cajas retiradas, divisor y nueva medición."],
["Los retrasos necesitan etapa","Vendedor, recepción, control, cálculo, operador, transbordos y aduanas son relojes distintos.¶Compara solo destinos y líneas similares y entiende la velocidad como intervalo."],
["El elogio del producto puede ser del vendedor","La fabricación pertenece al vendedor; Joyagoo aporta control general y fotos.¶Fotos QC, medidas, enlace y entrega son evidencia mejor, aunque no garantizan otro lote."],
["Prueba el soporte directamente","Hay elogios y críticas sobre respuesta. Complejidad, zona horaria y claridad influyen.¶Pregunta algo concreto antes de un pedido grande y después aporta número, estado, fecha, acción y prueba."],
["Cuidado con incentivos y poco detalle","Una reseña premiada no es necesariamente falsa, pero estrellas sin datos aportan poco; también una acusación sin pruebas.¶Separa hechos, afirmaciones y responsable y verifica políticas en fuentes oficiales."],
["La tienda de apps mide más la interfaz","Las reseñas de app hablan de búsqueda, pago, avisos y soporte, no tanto de una línea o vendedor.¶Separa comodidad digital del resultado del paquete."],
["Puntuación de calidad de reseñas","Valora destino, fechas, peso, medidas, ruta, flete inicial y final, control y resolución.¶Reduce el peso de estrellas, lenguaje promocional y relatos que mezclan responsabilidades."],
["Qué puede probar un principiante","Empieza pequeño y documentado; observa compra, despacho, llegada, control, soporte, ajuste y tracking.¶Tras recibir registra fechas, costes, ruta, pausas, embalaje y estado."],
["Conclusión equilibrada","Hay señales positivas sobre uso, comunicación y embalaje, y preocupaciones reales sobre coste, retraso y resolución.¶Las reglas oficiales definen la base; la comunidad indica qué comprobar antes de pagar."]]}
};

const fr:TranslationMap={
"joyagoo-fee-policy-free-agent-service-transaction-costs":{title:"Politique de frais Joyagoo : service gratuit et coûts payables",description:"Séparez le service d’achat gratuit des coûts vendeur, paiement, retour, options et colis.",meta:"POLITIQUE DE FRAIS · 15 MIN",sourceNote:"Périmètre vérifié le 29 août 2026 dans les guides publics actuels; politique et écran actifs font foi.",quickFacts:["Gratuit vise le service d’achat central","Produit et fret vendeur restent payables","Les options peuvent être facturées","Les retours peuvent être déduits","Le fret international est séparé"],rows:[
["Partir de l’affirmation exacte","Joyagoo présente le service d’agent d’achat comme gratuit. Une lecture précise indique l’absence d’un supplément distinct pour l’assistance centrale décrite.¶Cela ne rend pas gratuits le produit, le paiement, l’après-vente ou le colis international. Le périmètre doit accompagner le mot gratuit."],
["Attribuer chaque montant","Produit et livraison chinoise relèvent de la transaction vendeur; processeur ou banque peuvent appliquer une conversion distincte.¶Notez libellé, responsable, étape, remboursement et preuve. Ne transformez pas chaque ligne du paiement en frais Joyagoo."],
["Séparer aide standard et option","La gratuité centrale n’inclut pas automatiquement chaque demande d’entrepôt. Interface et politique actuelles contrôlent catalogue, disponibilité et prix.¶Conservez nom, montant, devise et dossier. Demandez quel risque l’option résout et si elle a été choisie activement."],
["Traiter le retour comme une branche distincte","Fret de retour ou traitement peuvent être déduits selon motif, accord vendeur, état et preuve. Un délai ne signifie pas retour gratuit.¶Gardez option, heure de statut, photos, motif, réponse, fret, traitement et calcul. Préférence et erreur vendeur confirmée restent distinctes."],
["Lire le fret international comme seconde transaction","Après stockage, le fret dépend de destination, méthode, poids, volume et colis. Un montant initial peut être estimation ou dépôt.¶Conservez colis, destination, ligne, mesures, emballage et ajustement. Il s’agit d’expliquer le montant sans promettre une route permanente."],
["Éviter la mauvaise attribution de devise et douane","Écart entre affichage, autorisation et relevé peut venir de devise, processeur, réseau, banque ou temps. Sans libellé, aucun frais Joyagoo n’est prouvé.¶La douane est aussi hors de la gratuité; les règles du pays et l’importation réelle contrôlent taxes et traitement."],
["Auditer avant publication ou paiement","Sauvegardez règle, date et formulation. Classez marchandise, fret intérieur, paiement, option, retour, colis international et douane.¶Le service gratuit se publie avec son périmètre. En cas de conflit, arrêtez, conservez les deux preuves et demandez une clarification écrite."],
["Tester trois exemples de transaction","Un achat standard peut associer service central gratuit et produit payable. Une option d’entrepôt choisie est distincte; un retour avec déduction ne crée pas rétroactivement des frais standard.¶Les exemples valent avec libellés et conditions. Laissez un montant non classé jusqu’à explication actuelle de la politique ou du support."],
["Divulguer conflits et changements","Une page peut changer, être traduite autrement ou contredire temporairement un champ actif. Conservez URL, titre, date et libellé puis décrivez précisément le conflit.¶Une réponse du support concerne son dossier et ne devient pas automatiquement règle mondiale durable. L’incertitude transparente vaut mieux qu’un pourcentage inventé."]]},
"joyagoo-buying-fees-guide":{title:"Tableur Joyagoo et guide d’achat 2026 : liens, frais, QC et livraison",description:"Guide vérifié du tableur Joyagoo : découverte, contrôle de l’annonce, frais, QC, retours et expédition internationale.",meta:"TABLEUR JOYAGOO · 15 MIN",sourceNote:"Base factuelle : guides officiels Joyagoo sur la recherche, l’achat, les frais et les statuts. Vérifiez annonce et paiement actifs.",quickFacts:["Les liens servent à découvrir","Service d’agent annoncé gratuit","Produit et livraison chinoise payants","Contrôle après l’arrivée","Fret international séparé"],rows:[
["Commencer avec le bon modèle","Joyagoo est un agent d’achat et d’expédition, pas le vendeur de chaque article. Achat du produit et colis international sont deux opérations distinctes.¶Le tableur sert à découvrir ; stock, prix, variante et admissibilité doivent être revérifiés sur la fiche active."],
["Ce que signifie service gratuit","L’explication officielle indique un service d’agent gratuit, mais produit, livraison intérieure, retour, fret international, douane et options restent possibles.¶Un budget sérieux sépare marchandise, coûts chinois, services additionnels et envoi mondial."],
["Utiliser les statuts comme jalons","Paiement, traitement, achat, envoi vendeur, arrivée, QC terminé, stockage et départ international correspondent à des responsabilités différentes.¶Notez statut et date pour adresser la demande au bon acteur et éviter d’annuler la mauvaise étape."],
["Créer une preuve avant paiement","Conservez lien vendeur, option, taille, couleur, prix, transport chinois, tableau de mesures et remarques. Une annonce peut changer.¶Ce dossier devient la référence du QC et d’un éventuel retour."],
["Comprendre le risque vendeur","Le vendeur contrôle stock, départ, exactitude de l’annonce et beaucoup de conditions de retour. L’agent aide sans créer des droits absents.¶Privilégiez les annonces documentées, options claires et mesures cohérentes plutôt que le prix le plus bas."],
["À l’arrivée à l’entrepôt","L’article est reçu, contrôlé globalement, photographié puis stocké. Les photos standard ne montrent pas chaque mesure ou étiquette.¶Confirmez d’abord identité et option, puis état, et demandez immédiatement l’image qui peut changer la décision."],
["Le retour est chronométré","La politique publiée prévoit 120 heures après QC Completed pour les produits éligibles, sous conditions de vendeur, état et emballage.¶Sans défaut accepté, l’acheteur paie généralement le retour ; environ 0,75 USD de service est aussi mentionné."],
["Le stockage est un temps de décision","Joyagoo publie 90 jours gratuits par article et une prolongation payante. Les dates diffèrent selon les arrivées.¶Fixez une limite interne antérieure pour garder du temps pour échange, photo, route et paiement."],
["L’international est une seconde décision d’achat","Une fois stockés, vous choisissez produits, destination, ligne et emballage. Restrictions, mesures et pays modifient les options.¶Le premier montant peut être estimatif et évoluer après emballage ou nouvelle mesure."],
["Séparer douane et assurance","Le destinataire assume taxes, amendes ou retours possibles ; une déclaration système ne garantit pas le dédouanement.¶L’assurance dépend de la ligne, du pays et du barème. Enregistrez couverture et exclusions avant paiement."],
["Checklist avant validation","Avant le produit, vérifiez lien, variante, vendeur et preuves attendues. Avant 120 heures, comparez photos et dossier.¶Avant le colis, contrôlez délais, emballage, poids facturable, déclaration, assurance, adresse et règles actives."]]},
"joyagoo-qc-return-window-guide":{title:"Photos QC Joyagoo et retour sous 5 jours : guide de décision",description:"Comparer les photos à l’annonce, demander des preuves utiles, documenter les défauts et agir dans les 120 heures publiées.",meta:"QC & RETOURS · 13 MIN",sourceNote:"Base factuelle : guide d’achat, politique de retour, présentation du service et conseils de réception Joyagoo.",quickFacts:["QC après l’arrivée","Retour : 120 heures","Éligibilité vendeur nécessaire","Emballage important","Les photos doivent trancher"],rows:[
["Le QC n’est pas une garantie","L’entrepôt effectue un contrôle général avec photos, pas une authentification ni une promesse de perfection.¶Demandez si les images prouvent identité, variante, mesures et défauts susceptibles de modifier la décision."],
["Préparer la référence","Conservez annonce, option, guide de taille, accessoires et détails essentiels. Sans référence, seule l’apparence peut être jugée.¶Une note par commande facilite photo supplémentaire et retour malgré une annonce modifiée."],
["Identité avant finition","Vérifiez type, couleur, modèle, étiquette de taille, quantité et pièces avant coutures ou surfaces.¶En cas de doute, demandez étiquette, code ou mesure au lieu de deviner avec la lumière."],
["Inspecter dans un ordre fixe","Forme, face, dos, assemblages, pièces, surface, étiquettes, accessoires et emballage doivent être examinés systématiquement.¶Distinguez variation esthétique et panne fonctionnelle en tenant compte du prix, de l’usage et du retour."],
["Demander des photos décisives","Mesure, gros plan d’une tache, face opposée, étiquette ou accessoires complets sont utiles s’ils peuvent changer Keep ou Return.¶Précisez emplacement et objectif ; davantage de photos sans précision peut consommer le délai."],
["Connaître le départ du délai","Les cinq jours ou 120 heures partent du statut QC Completed, pas de l’ouverture tardive des images.¶Notez chaque échéance et n’attendez pas les autres articles destinés au regroupement."],
["L’éligibilité n’est pas automatique","Vendeur et plateforme doivent accepter le retour ; l’article doit souvent rester revendable avec l’emballage requis.¶Vérifiez cette souplesse avant achat et évitez toute modification irréversible."],
["Comprendre coûts et responsabilité","Sans défaut confirmé, l’acheteur paie généralement le retour et la politique cite environ 0,75 USD de service.¶Comparez remboursement, transport et temps ; mauvaise taille et petit fil n’ont pas le même poids."],
["Rédiger une demande exploitable","Indiquez commande, variante et différence observable, puis joignez annonce sauvegardée et photo correspondante.¶Taille erronée, fissure ou accessoire absent se vérifient mieux qu’une plainte générale."],
["QC des produits fragiles","Chaussures, sacs, lunettes et objets rigides demandent angles, symétrie et contrôle des parties structurelles.¶Le QC et la consigne d’emballage doivent fonctionner ensemble pour prévenir les dégâts."],
["Après la livraison","Contrôlez les dommages visibles avec le livreur et gardez carton, étiquette, protection, facture et photos.¶Les guides demandent une preuve rapide : deux jours ouvrés pour un dommage découvert après et contact sous 72 heures."],
["Système QC compact","Vérifiez identité, qualité décisive, preuve manquante, délai et coût.¶Enregistrez clairement garder, demander une photo, échanger ou retourner pour rendre le processus reproductible."]]},
"joyagoo-warehouse-rehearsal-shipping-guide":{title:"Entrepôt et livraison Joyagoo : 90 jours, pré-emballage et regroupement",description:"De l’entrepôt au colis : délais, consolidation, emballage, lignes, ajustements, assurance et suivi.",meta:"ENTREPÔT & LIVRAISON · 15 MIN",sourceNote:"Base factuelle : guides officiels d’achat, logistique, regroupement, statuts, assurance et suivi.",quickFacts:["90 jours gratuits par article","Pré-emballage à 20 CNY","Lignes filtrées par produit","Coupons non cumulables","Suivi parfois retardé"],rows:[
["Utiliser l’entrepôt pour planifier","L’entrepôt relie les achats vendeurs au colis international et permet QC, retour, regroupement et comparaison.¶Suivez arrivée, décision, échéance et colis prévu pour ne perdre aucun article."],
["Comprendre les 90 jours","Le guide publie 90 jours gratuits par produit ; chaque arrivée peut donc avoir une date différente.¶Fixez une limite plus tôt pour conserver du temps pour échange, photo et paiement."],
["Finir le QC avant regroupement","Seuls les articles confirmés doivent entrer dans le plan final, car certaines modifications d’emballage compliquent un retour.¶Validez identité, état et protection avant de les traiter comme une unité."],
["Pourquoi regrouper peut économiser","Plusieurs petits colis répètent premier poids et manutention. Une boîte commune peut réduire ces répétitions.¶Une grande boîte peut toutefois déclencher volume, limites ou risque concentré ; comparez les divisions."],
["Regrouper par compatibilité","Textiles, chaussures, fragiles et surfaces sensibles exigent des protections différentes ; un objet rigide fixe les dimensions.¶Regroupez selon forme et risque, pas seulement selon la date."],
["Soumission standard ou pré-emballage","La voie standard commence par une estimation puis un ajustement. Le service à 20 CNY emballe d’abord et donne des mesures plus réalistes.¶Ce n’est pas une remise ; il vaut si l’information change ligne, division ou retrait de boîtes."],
["Écrire les consignes article par article","Précisez quelle boîte retirer, quelle forme protéger et où renforcer. Une consigne générale peut être contradictoire.¶Moins de boîte réduit le volume ; renforcer ajoute du poids ; le vide peut abîmer les formes."],
["Lire les lignes après définition du colis","Produit, destination, poids, dimensions et restrictions déterminent les lignes disponibles. Un ancien tableau n’est pas une garantie.¶Comparez formule, limites, assurance et transferts avec des données réalistes."],
["Séparer estimation et facture réelle","Le système estime, l’entrepôt mesure après emballage et le transporteur peut remesurer.¶Conservez les valeurs et vérifiez que différence, formule et arrondi s’expliquent."],
["Utiliser le coupon au bon moment","Les coupons concernent le fret international et ne sont pas cumulables ; ils ne réduisent pas le produit.¶Évaluez-les après choix du colis et de la ligne."],
["Assurance et douane restent liées à la ligne","Couverture, saisie, perte ou dommage dépendent du pays et de la ligne ; le passage en douane n’est jamais garanti.¶Vérifiez déclaration, responsabilités, exclusions et preuves avant paiement."],
["Suivi et preuve de livraison","Après départ, le suivi peut rester silencieux pendant les transferts sans prouver une perte.¶En cas de dommage, documentez extérieur, étiquette, protection et produit dans le délai officiel."],
["Calendrier pratique","Jour zéro correspond à l’arrivée de chaque article. Traitez QC et retour, formez les groupes et fixez une échéance interne.¶Avant envoi, confirmez mesures, emballage, ligne, assurance, déclaration, adresse et coupon."]]},
"volumetric-weight-guide":{title:"Poids réel et volumétrique Joyagoo : calcul du colis",description:"Mesurer les cartons, comparer les diviseurs par ligne et comprendre pourquoi un colis léger mais grand peut coûter plus cher.",meta:"CALCUL LIVRAISON · 12 MIN",sourceNote:"Base factuelle : guides Joyagoo sur les poids, tableau des lignes, facturation estimée et guide d’achat.",quickFacts:["Le poids supérieur peut compter","Diviseurs variables","Emballage inclus","Estimation non définitive","Transporteur peut remesurer"],rows:[
["Même poids, coût différent","Le transport utilise masse et espace ; certaines lignes comparent balance et calcul dimensionnel puis facturent le plus élevé.¶L’estimation correcte part du carton fini, pas des articles nus."],
["Ce que comprend le poids réel","Produit, boîte commerciale, protection, remplissage et carton extérieur sont inclus. Les consignes modifient le résultat.¶Retirer réduit masse et protection ; renforcer ajoute du poids mais peut éviter un dommage."],
["Calcul du volume","La formule publiée est longueur × largeur × hauteur en centimètres divisée par la valeur de la ligne. Les exemples citent 5000, 6000, 7000 et 8000.¶Confirmez toujours seuil, unités et arrondi ; aucun diviseur n’est universel."],
["Exemple chiffré","Un carton de 50 × 40 × 30 cm représente 60 000 cm³ : 12 kg avec 5000, 10 avec 6000 et 7,5 avec 8000.¶S’il pèse 6 kg, le volume peut contrôler les trois facturations."],
["Trouver les causes de volume","Boîtes à chaussures, chapeaux, doudounes et cartons à moitié vides fixent souvent les dimensions.¶Identifiez quel objet impose longueur, largeur et hauteur avant de demander une modification."],
["Les seuils changent la réponse","Certaines lignes appliquent le volume après une longueur, d’autres toujours, d’autres utilisent un test de sac.¶Comparez le total avec les mêmes mesures plutôt que des tarifs au kilo isolés."],
["L’estimation reste provisoire","Le système suppose un emballage ; retrait, renfort et placement modifient l’objet fini.¶Gardez une fourchette et considérez le colis physique comme donnée principale."],
["Le transporteur peut remesurer","Scanner, arrondi ou tassement peuvent amener le prestataire à confirmer ou corriger la mesure d’entrepôt.¶Consultez la facturation réelle après envoi avant de conclure à une erreur."],
["Quand les 20 CNY sont utiles","Le pré-emballage donne des dimensions plus réalistes avant paiement sans changer formule ni tarif.¶Il aide avec plusieurs boîtes, formes mixtes, seuils ou lignes sensibles à quelques centimètres."],
["Un meilleur tableur d’expédition","Notez poids, emballage nécessaire et retirable, dimensions et formule de chaque ligne, puis calculez séparément.¶Ajoutez date et statut estimé : l’outil compare les choix sans promettre un total fixe."],
["Priorité des décisions d’emballage","Protégez d’abord, retirez ensuite l’inutile, rangez les compatibles, comparez les divisions puis calculez.¶Ainsi, l’économie de volume ne détruit pas l’objectif de livraison sûre."],
["Contrôle final","Confirmez dimensions, poids réel, diviseur, seuil, arrondi, règle du plus élevé et statut estimé ou final.¶Conservez consignes, coupon, assurance et déclaration pour expliquer les ajustements."]]},
"joyagoo-reviews-buyer-signals":{title:"Avis Joyagoo : éloges, critiques et points à vérifier",description:"Analyse équilibrée séparant règles officielles et signaux clients sur commande, QC, support, coût, retard et réclamation.",meta:"AVIS ACHETEURS · 13 MIN",sourceNote:"Signaux publics de Trustpilot, App Store et Reddit vérifiés en août 2026. Ce sont des expériences individuelles, pas des garanties.",quickFacts:["Avis anecdotiques","Pays et ligne changent le résultat","Facilité et aide appréciées","Coûts et retards critiqués","Les règles officielles dominent"],rows:[
["Lire un avis d’agent","Un avis mélange souvent vendeur, agent, transporteur et douane. Sans étape précise, la cause reste incertaine.¶Utilisez les avis pour découvrir des questions, pas pour garantir produit, délai ou douane."],
["Ce que les avis positifs soulignent","Facilité, communication, bon état, emballage sûr et livraison rapide reviennent souvent.¶Le signal est plus fort avec destination, ligne, poids, dates et différence entre estimation et total."],
["Alerte principale : le coût","Certains avis mentionnent fret élevé ou supplément, cohérents avec paiement séparé et poids volumétrique possible.¶Il faut estimation, mesures finales, boîtes retirées, diviseur et nouvelle mesure pour juger."],
["Un retard a besoin d’une étape","Vendeur, réception, QC, calcul, transporteur, transferts et douane ont des horloges différentes.¶Comparez seulement pays et lignes proches et pensez en fourchette."],
["Le produit peut refléter le vendeur","La fabrication appartient au vendeur ; Joyagoo fournit contrôle général et photos.¶Lien, photos QC, mesures et livraison offrent de meilleurs indices sans garantir un nouveau lot."],
["Tester directement le support","Les retours sont positifs et négatifs ; complexité, fuseau et précision comptent.¶Posez une question concrète avant une grosse commande puis fournissez numéro, statut, date, action et preuve."],
["Attention aux incitations et au manque de détail","Un avis récompensé n’est pas forcément faux, mais des étoiles sans données ont peu de valeur, comme une accusation sans preuve.¶Séparez faits, affirmations et responsable, puis vérifiez la règle officielle."],
["Les notes d’app décrivent surtout l’interface","Recherche, paiement, alertes et support dominent les avis mobiles, pas une ligne internationale précise.¶Séparez confort logiciel et résultat logistique."],
["Score de qualité d’un avis","Valorisez destination, dates, poids, dimensions, ligne, fret initial et final, QC et issue de réclamation.¶Réduisez le poids des étoiles ou récits qui confondent les parties."],
["Test prudent pour un débutant","Commencez petit et documenté ; observez achat, envoi vendeur, arrivée, QC, support, ajustement et suivi.¶Après réception, notez dates, coûts, ligne, pauses, emballage et état."],
["Conclusion équilibrée","Les signaux positifs concernent usage, communication et emballage ; les inquiétudes portent sur coût, retard et résolution.¶Les règles officielles fixent la base, la communauté indique quoi vérifier avant paiement."]]}
};

const it:TranslationMap={
"joyagoo-fee-policy-free-agent-service-transaction-costs":{title:"Politica tariffe Joyagoo: servizio gratuito e costi pagabili",description:"Separa il servizio base gratuito da costi del venditore, pagamento, reso, opzioni e pacco.",meta:"POLITICA TARIFFE · 15 MIN",sourceNote:"Ambito verificato il 29 agosto 2026 sulle guide pubbliche attuali; contano politica e checkout attivi.",quickFacts:["Gratis indica il servizio base","Prodotto e trasporto nazionale si pagano","Le opzioni possono costare","Il reso può avere detrazioni","Il trasporto internazionale è separato"],rows:[
["Partire dall’affermazione esatta","Joyagoo descrive come gratuito il servizio dell’agente di acquisto. La lettura precisa esclude un supplemento separato per l’assistenza base descritta.¶Non rende gratuiti prodotto, pagamento, post-vendita o pacco internazionale. L’ambito deve accompagnare sempre la parola gratis."],
["Assegnare ogni importo","Prodotto e spedizione cinese derivano dalla transazione del venditore; processore o banca possono applicare conversioni separate.¶Registra etichetta, responsabile, fase, rimborso e prova. Non chiamare tariffa Joyagoo ogni cifra al checkout."],
["Separare assistenza standard e opzioni","La gratuità base non include automaticamente ogni richiesta di magazzino. Interfaccia e politica attuali controllano catalogo, disponibilità e prezzo.¶Salva nome, importo, valuta e pratica. Verifica quale rischio risolve l’opzione e se il compratore l’ha scelta."],
["Trattare il reso come ramo distinto","Trasporto di ritorno o gestione possono essere detratti secondo motivo, consenso del venditore, stato e prove. Una finestra non significa reso gratuito.¶Conserva opzione, ora, foto, motivo, risposta, trasporto, gestione e calcolo. Preferenza ed errore confermato sono casi diversi."],
["Leggere il trasporto internazionale come seconda transazione","Dopo il deposito, il costo dipende da destinazione, metodo, peso, volume e pacco. Un importo iniziale può essere stima o deposito.¶Salva pacco, destinazione, linea, misure, imballo e rettifica. Spiega il valore senza promettere rotta o formula permanente."],
["Non attribuire male valuta e dogana","Differenze tra display, autorizzazione ed estratto possono derivare da valuta, processore, rete, banca o momento. Senza etichetta non provano una tariffa Joyagoo.¶Anche la dogana è fuori dalla gratuità; regole del paese e importazione reale controllano imposte e gestione."],
["Verificare prima di pubblicare o pagare","Salva regola, data e testo attuali. Raggruppa merce, trasporto interno, pagamento, extra, reso, pacco internazionale e dogana.¶Il servizio gratuito va indicato con il suo ambito. Se politica e schermata divergono, fermati, salva entrambe e chiedi chiarimento scritto."],
["Provare tre esempi di transazione","Un acquisto standard può avere servizio base gratuito e prodotto pagato. Un’opzione di magazzino scelta resta separata; un reso con detrazione non crea retroattivamente una tariffa standard.¶Gli esempi valgono solo con etichette e condizioni. Lascia aperto un importo finché politica o supporto attuali lo spiegano."],
["Dichiarare conflitti e cambiamenti","Le pagine possono cambiare, essere tradotte diversamente o non coincidere temporaneamente col campo attivo. Salva URL, titolo, data ed etichetta e descrivi il conflitto.¶Una risposta del supporto appartiene al caso e non diventa automaticamente regola globale. L’incertezza trasparente è migliore di una percentuale inventata."]]},
"joyagoo-buying-fees-guide":{title:"Foglio Joyagoo e guida acquisti 2026: link, costi, QC e spedizione",description:"Guida verificata del foglio Joyagoo su scoperta, controllo inserzione, costi, QC, resi e spedizione internazionale.",meta:"FOGLIO JOYAGOO · 15 MIN",sourceNote:"Base fattuale: guide ufficiali Joyagoo su ricerca, acquisto, tariffe e stati. Verifica inserzione e checkout attivi.",quickFacts:["I link servono alla scoperta","Servizio agente indicato gratuito","Prodotto e consegna cinese si pagano","Controllo dopo l’arrivo","Trasporto internazionale separato"],rows:[
["Parti dal modello corretto","Joyagoo è un agente d’acquisto e spedizione, non il venditore originale di ogni articolo. Prodotto e pacco internazionale sono operazioni separate.¶Il foglio serve a scoprire; disponibilità, prezzo, variante e spedibilità vanno ricontrollati sulla pagina attiva."],
["Cosa significa servizio gratuito","La spiegazione ufficiale definisce gratuito il servizio agente, ma restano prodotto, consegna interna, reso, trasporto internazionale, dogana e opzioni.¶Un budget realistico separa merce, costi cinesi, servizi extra e spedizione mondiale."],
["Usa gli stati come checkpoint","Pagamento, elaborazione, acquistato, venditore spedito, arrivato, QC completato, depositato e spedito indicano responsabilità diverse.¶Salva stato e data per rivolgere ogni richiesta al venditore, magazzino, agente o corriere corretto."],
["Crea un registro prima di pagare","Salva link, opzione, taglia, colore, prezzo, consegna nazionale, tabella misure e note. L’inserzione può cambiare.¶Questo registro è il riferimento per QC e un’eventuale richiesta di reso."],
["Comprendi il rischio del venditore","Il venditore controlla stock, partenza, accuratezza e molte condizioni di reso. L’agente può aiutare ma non creare diritti mancanti.¶Preferisci inserzioni chiare con opzioni, misure e immagini coerenti anche se non sono le più economiche."],
["Cosa accade in magazzino","Dopo l’arrivo l’articolo viene registrato, controllato in modo generale, fotografato e depositato. Le foto standard non mostrano ogni dettaglio.¶Conferma identità e opzione, poi condizioni, e chiedi subito la prova che può cambiare la decisione."],
["Il reso ha una scadenza","La politica pubblicata indica 120 ore dopo QC Completed per gli articoli idonei, con condizioni di venditore, stato e imballo.¶Senza difetto accettato il compratore paga di solito il ritorno; è citata anche una tariffa di circa 0,75 USD."],
["Il deposito è tempo di pianificazione","Joyagoo pubblica 90 giorni gratuiti per articolo con estensione a pagamento. Arrivi diversi hanno scadenze diverse.¶Imposta una data interna precedente per mantenere spazio per cambio, foto, rotta e pagamento."],
["La spedizione internazionale è una seconda scelta","Con gli articoli depositati scegli contenuto, destinazione, linea e imballo. Restrizioni, misure e paese cambiano le opzioni.¶Il primo importo può essere stimato e corretto dopo imballaggio o nuova misurazione."],
["Separa dogana e assicurazione","Il destinatario resta responsabile di tasse, multe o ritorni possibili; la dichiarazione di sistema non garantisce lo sdoganamento.¶Assicurazione e copertura dipendono da linea, paese e standard attuale. Salvale prima di pagare."],
["Checklist del compratore","Prima del prodotto conferma link, variante, venditore e prove attese. Entro 120 ore confronta foto e registro.¶Prima del pacco controlla scadenze, imballo, peso addebitabile, dichiarazione, assicurazione, indirizzo e regole attive."]]},
"joyagoo-qc-return-window-guide":{title:"Foto QC Joyagoo e reso in 5 giorni: guida decisionale",description:"Confrontare foto e inserzione, chiedere prove utili, documentare difetti e agire entro le 120 ore pubblicate.",meta:"QC E RESI · 13 MIN",sourceNote:"Base fattuale: guida acquisti, politica resi, panoramica del servizio e avvisi di ricezione Joyagoo.",quickFacts:["QC dopo l’arrivo","Reso: 120 ore","Serve idoneità del venditore","L’imballo conta","Le foto devono chiarire"],rows:[
["Il QC non è una garanzia totale","Il magazzino svolge un controllo generale con foto, non autenticazione o perfezione garantita.¶Chiedi se le immagini provano identità, variante, misure e difetti che cambiano la scelta."],
["Prepara il riferimento","Salva inserzione, opzione, tabella taglie, accessori e dettagli essenziali. Senza riferimento puoi giudicare solo l’aspetto.¶Una nota per ordine facilita foto extra e reso se la pagina cambia."],
["Identità prima della fattura","Controlla tipo, colore, modello, etichetta taglia, quantità e parti prima di cuciture o superfici.¶In caso di dubbio chiedi etichetta, codice o misura invece di dedurre da luce e prospettiva."],
["Ispeziona in ordine fisso","Forma, fronte, retro, giunzioni, hardware, superfici, etichette, accessori e imballo vanno esaminati sempre nello stesso ordine.¶Distingui variazione estetica da guasto funzionale considerando prezzo, uso e costo del ritorno."],
["Richiedi foto che cambiano la decisione","Misura, dettaglio di una macchia, lato opposto, etichetta o accessori completi servono se possono cambiare Keep o Return.¶Indica posizione e scopo; più foto generiche possono consumare il termine senza risolvere."],
["Conosci l’inizio del termine","Cinque giorni o 120 ore partono dallo stato QC Completed, non dalla successiva apertura delle immagini.¶Registra ogni scadenza e non attendere altri articoli da consolidare."],
["L’idoneità non è automatica","Venditore e piattaforma devono sostenere il reso; l’articolo deve spesso restare rivendibile e correttamente confezionato.¶Verifica la flessibilità prima dell’acquisto ed evita modifiche irreversibili."],
["Costi e responsabilità","Senza difetto confermato il compratore paga normalmente il ritorno e la politica cita circa 0,75 USD di servizio.¶Confronta rimborso, trasporto e tempo; taglia errata e filo sciolto hanno peso diverso."],
["Scrivi una richiesta utilizzabile","Indica ordine, variante e differenza osservabile e allega inserzione salvata e foto corrispondente.¶Taglia sbagliata, rottura o accessorio assente sono verificabili; un reclamo vago no."],
["QC per merce fragile","Scarpe, borse, occhiali e oggetti rigidi richiedono angoli, simmetria e controllo delle parti strutturali.¶QC e istruzioni di imballo devono lavorare insieme contro i danni successivi."],
["Dopo la consegna","Controlla danni visibili col corriere e conserva scatola, etichetta, protezione, fattura e foto.¶Le guide chiedono prove rapide: due giorni lavorativi per danni scoperti dopo e contatto entro 72 ore."],
["Sistema QC compatto","Controlla identità, qualità decisiva, prova mancante, termine e costo.¶Registra chiaramente tenere, chiedere foto, cambiare o rendere per creare un processo ripetibile."]]},
"joyagoo-warehouse-rehearsal-shipping-guide":{title:"Magazzino e spedizione Joyagoo: 90 giorni, prova e consolidamento",description:"Dal magazzino al pacco: scadenze, consolidamento, imballo, rotte, correzioni, assicurazione e tracking.",meta:"MAGAZZINO E SPEDIZIONE · 15 MIN",sourceNote:"Base fattuale: guide ufficiali su acquisto, logistica, consolidamento, stati, assicurazione e tracking.",quickFacts:["90 giorni gratis per articolo","Prova indicata a 20 CNY","Rotte filtrate per prodotto","Coupon non cumulabili","Tracking può tardare"],rows:[
["Usa il magazzino per pianificare","Il magazzino collega gli ordini dei venditori al pacco internazionale e permette QC, reso, raggruppamento e confronto.¶Registra arrivo, decisione, scadenza e pacco previsto per non dimenticare nulla."],
["Comprendi i 90 giorni","La guida pubblica 90 giorni gratuiti per prodotto, quindi ogni arrivo può avere una data diversa.¶Imposta un limite precedente per mantenere tempo per cambio, foto e pagamento."],
["Completa il QC prima di consolidare","Solo articoli confermati dovrebbero entrare nel piano finale, perché alcune modifiche di imballo complicano un reso.¶Conferma identità, stato e protezione prima di trattarli come unità."],
["Perché consolidare può risparmiare","Pacchi separati ripetono primo peso e gestione. Una scatola comune può ridurre tali ripetizioni.¶Una scatola grande può però attivare volume, limiti o rischio concentrato; confronta anche le divisioni."],
["Raggruppa per compatibilità","Tessuti, scarpe, fragili e superfici delicate richiedono protezioni diverse; un oggetto rigido fissa le dimensioni.¶Raggruppa per forma e rischio, non solo per data."],
["Invio standard o prova imballo","Lo standard parte da una stima e viene corretto dopo. La prova a 20 CNY imballa prima e fornisce misure più realistiche.¶Non è uno sconto; vale se l’informazione cambia rotta, divisione o rimozione scatole."],
["Scrivi istruzioni per articolo","Indica quale scatola rimuovere, quale forma proteggere e dove rinforzare. Richieste generiche possono essere contraddittorie.¶Meno scatola riduce volume; rinforzo aggiunge peso; il vuoto può deformare."],
["Leggi le rotte quando il pacco è noto","Prodotto, destinazione, peso, misure e restrizioni determinano le linee. Una tabella vecchia non garantisce nulla.¶Confronta formula, limiti, assicurazione e passaggi con dati realistici."],
["Separa stima e addebito reale","Il sistema stima, il magazzino misura dopo il confezionamento e il corriere può rimisurare.¶Conserva i valori e verifica che differenza, formula e arrotondamento siano spiegabili."],
["Usa i coupon nel momento giusto","I coupon valgono solo sul trasporto internazionale e non sono cumulabili; non riducono il prodotto.¶Valutali dopo pacco e rotta."],
["Assicurazione e dogana dipendono dalla linea","Copertura, sequestro, perdita o danno dipendono da paese e linea; lo sdoganamento non è garantito.¶Controlla dichiarazione, responsabilità, esclusioni e prove prima del pagamento."],
["Tracking e prova di consegna","Dopo la partenza il tracking può fermarsi durante i trasferimenti senza provare una perdita.¶In caso di danno documenta esterno, etichetta, protezione e prodotto entro i termini."],
["Calendario pratico","Il giorno zero è l’arrivo di ogni articolo. Risolvi QC e reso, crea gruppi compatibili e fissa una data interna.¶Prima di inviare conferma misure, imballo, rotta, assicurazione, dichiarazione, indirizzo e coupon."]]},
"volumetric-weight-guide":{title:"Peso reale e volumetrico Joyagoo: matematica del pacco",description:"Misurare le scatole, confrontare i divisori per rotta e capire perché un pacco leggero ma grande può costare di più.",meta:"CALCOLO SPEDIZIONE · 12 MIN",sourceNote:"Base fattuale: guide Joyagoo sui pesi, tabella rotte, fatturazione stimata e guida acquisti.",quickFacts:["Può contare il peso maggiore","Divisori variabili","L’imballo è incluso","La stima non è finale","Il corriere può rimisurare"],rows:[
["Stesso peso, costo diverso","Il trasporto usa massa e spazio; alcune linee confrontano bilancia e calcolo dimensionale e addebitano il maggiore.¶La stima corretta parte dal cartone finito, non dai prodotti nudi."],
["Cosa include il peso reale","Prodotto, scatola commerciale, protezione, riempimento e imballo esterno sono inclusi. Le richieste cambiano il risultato.¶Rimuovere riduce peso e protezione; rinforzare aggiunge peso ma può evitare danni."],
["Calcolo del volume","La formula pubblicata è lunghezza × larghezza × altezza in centimetri divisa per il valore della rotta. Gli esempi citano 5000, 6000, 7000 e 8000.¶Conferma soglia, unità e arrotondamento: non esiste un divisore universale."],
["Esempio numerico","Una scatola 50 × 40 × 30 cm vale 60.000 cm³: 12 kg con 5000, 10 con 6000 e 7,5 con 8000.¶Se pesa davvero 6 kg, il volume può governare tutte e tre le linee."],
["Trova le cause del volume","Scatole scarpe, cappelli, piumini e cartoni mezzi vuoti fissano spesso le dimensioni esterne.¶Identifica cosa determina lunghezza, larghezza e altezza prima di chiedere modifiche."],
["Le soglie cambiano la risposta","Alcune linee applicano volume dopo una lunghezza, altre sempre, altre con test busta o divisori propri.¶Confronta il totale usando le stesse misure, non tariffe isolate per chilo."],
["La stima resta provvisoria","Il sistema assume un imballo; rimozione, rinforzo e disposizione cambiano il pacco finito.¶Conserva un intervallo e considera decisivo l’oggetto fisico."],
["Il corriere può rimisurare","Scanner, arrotondamento o assestamento possono confermare o correggere la misura del magazzino.¶Controlla i dettagli reali dopo la spedizione prima di dichiarare un errore."],
["Quando servono 20 CNY","La prova fornisce misure più realistiche prima del pagamento senza cambiare formula o tariffa.¶Aiuta con molte scatole, forme miste, soglie o rotte sensibili a pochi centimetri."],
["Un foglio di spedizione migliore","Registra peso, imballo necessario e rimovibile, misure e formula di ogni linea, poi calcola separatamente.¶Aggiungi data e stato stimato: confronta decisioni senza promettere un totale fisso."],
["Priorità dell’imballo","Proteggi prima, rimuovi l’inutile, ordina i compatibili, confronta divisioni e infine calcola le rotte.¶Così il risparmio di volume non distrugge la sicurezza."],
["Controllo finale","Conferma misure, peso reale, divisore, soglia, arrotondamento, regola del maggiore e stato stimato o finale.¶Salva istruzioni, coupon, assicurazione e dichiarazione per spiegare correzioni."]]},
"joyagoo-reviews-buyer-signals":{title:"Recensioni Joyagoo: elogi, dubbi e cosa verificare",description:"Analisi equilibrata che separa regole ufficiali e segnali degli utenti su ordini, QC, supporto, costi, ritardi e reclami.",meta:"RECENSIONI ACQUIRENTI · 13 MIN",sourceNote:"Segnali pubblici da Trustpilot, App Store e Reddit controllati ad agosto 2026. Sono esperienze individuali, non garanzie.",quickFacts:["Recensioni aneddotiche","Paese e rotta cambiano l’esito","Apprezzati facilità e aiuto","Criticati costi e ritardi","Le regole ufficiali restano base"],rows:[
["Come leggere una recensione di agente","Una recensione mescola spesso venditore, agente, corriere e dogana. Senza fase precisa la causa resta incerta.¶Usa i commenti per trovare domande, non per garantire prodotto, tempo o dogana."],
["Cosa viene elogiato","Facilità, comunicazione, buone condizioni, imballo sicuro e consegna rapida ricorrono nei commenti positivi.¶Il segnale è più forte con paese, linea, peso, date e differenza tra stima e totale."],
["Avvertenza principale: il costo","Alcuni citano trasporto alto o supplementi, coerenti con pagamento separato e possibile volume.¶Servono stima, misure finali, scatole rimosse, divisore e nuova misurazione per giudicare."],
["Un ritardo richiede una fase","Venditore, ricezione, QC, calcolo, corriere, trasferimenti e dogana hanno orologi diversi.¶Confronta solo destinazioni e linee simili e considera un intervallo."],
["Il prodotto può riflettere il venditore","La fabbricazione appartiene al venditore; Joyagoo offre controllo generale e foto.¶Link, foto QC, misure e consegna sono indizi migliori senza garantire un altro lotto."],
["Testa direttamente il supporto","Esistono elogi e critiche; complessità, fuso e precisione incidono.¶Fai una domanda concreta prima di un grande ordine e poi fornisci numero, stato, data, azione e prova."],
["Attenzione a incentivi e poco dettaglio","Una recensione premiata non è per forza falsa, ma stelle senza dati valgono poco, come un’accusa senza prove.¶Separa fatti, affermazioni e responsabile e verifica la policy ufficiale."],
["Le valutazioni app descrivono l’interfaccia","Ricerca, pagamento, notifiche e supporto dominano le recensioni mobili, non una specifica linea internazionale.¶Separa comodità software e risultato logistico."],
["Punteggio di qualità delle recensioni","Valuta paese, date, peso, misure, linea, trasporto iniziale e finale, QC ed esito del reclamo.¶Riduci il peso di stelle e racconti che confondono i ruoli."],
["Test prudente per un principiante","Inizia piccolo e documentato; osserva acquisto, invio venditore, arrivo, QC, supporto, correzione e tracking.¶Dopo la consegna registra date, costi, linea, pause, imballo e stato."],
["Conclusione equilibrata","I segnali positivi riguardano uso, comunicazione e imballo; le preoccupazioni costi, ritardi e soluzione.¶Le regole ufficiali fissano la base, la comunità indica cosa controllare prima di pagare."]]}
};

const rehearsalArticleCorrections={
  de:{fact:"Offizielle Seiten: 20 CNY / 3 USD",warehouseHeading:"Standardabgabe oder Probeverpackung",warehouseText:"Bei Standardabgabe beginnt die Zahlung mit einer geschätzten Fracht und wird nach dem Packen angepasst. Zwei offizielle Hilfeseiten zeigen derzeit unterschiedliche Preise für die Probeverpackung: 20 CNY in Shopping Guidance und 3 USD pro Paket bei Value Added Services.¶Der Service ist kein Rabatt. Prüfe den Live-Checkout und nutze ihn, wenn realistischere Maße Route, Teilung oder Kartonentfernung verändern können.",weightHeading:"Wann Probeverpackung sinnvoll ist",weightText:"Die offiziellen Hilfeseiten zeigen derzeit 20 CNY beziehungsweise 3 USD pro Paket. Prüfe den Live-Checkout; die Probeverpackung liefert vor der endgültigen Zahlung realistischere Maße, ändert aber weder Formel noch Tarif.¶Sie ist besonders nützlich bei mehreren Boxen, gemischten Formen, Grenzwerten oder Routen, deren Reihenfolge von wenigen Zentimetern abhängt."},
  es:{fact:"Páginas oficiales: 20 CNY / 3 USD",warehouseHeading:"Envío estándar o ensayo de embalaje",warehouseText:"El envío estándar empieza con un flete estimado y se ajusta después del embalaje. Dos páginas oficiales muestran precios distintos para el ensayo: 20 CNY en Shopping Guidance y 3 USD por paquete en Value Added Services.¶No es un descuento. Verifica el checkout y úsalo cuando unas medidas más realistas puedan cambiar la ruta, la división o la retirada de cajas.",weightHeading:"Cuándo conviene el ensayo de embalaje",weightText:"Las páginas oficiales muestran actualmente 20 CNY y 3 USD por paquete. Verifica el checkout; el ensayo ofrece medidas más realistas antes del pago final, pero no modifica la fórmula ni la tarifa de la ruta.¶Resulta útil con varias cajas, formas mixtas, límites o rutas cuya posición cambia por pocos centímetros."},
  fr:{fact:"Pages officielles : 20 CNY / 3 USD",warehouseHeading:"Soumission standard ou pré-emballage",warehouseText:"La soumission standard commence par un fret estimé, ajusté après emballage. Deux pages officielles affichent actuellement des prix différents : 20 CNY dans Shopping Guidance et 3 USD par colis dans Value Added Services.¶Ce n’est pas une remise. Vérifiez le paiement actif et utilisez le service lorsque des mesures réalistes peuvent modifier la ligne, la séparation ou le retrait des boîtes.",weightHeading:"Quand le pré-emballage est utile",weightText:"Les pages officielles affichent actuellement 20 CNY et 3 USD par colis. Vérifiez le paiement actif ; le service donne des mesures plus réalistes avant le règlement final sans modifier la formule ni le tarif.¶Il est utile avec plusieurs boîtes, des formes mixtes, des seuils ou des lignes sensibles à quelques centimètres."},
  it:{fact:"Pagine ufficiali: 20 CNY / 3 USD",warehouseHeading:"Invio standard o prova d’imballaggio",warehouseText:"L’invio standard parte da un trasporto stimato e viene corretto dopo l’imballo. Due pagine ufficiali mostrano prezzi diversi per la prova: 20 CNY in Shopping Guidance e 3 USD per pacco in Value Added Services.¶Non è uno sconto. Verifica il checkout e usala quando misure più realistiche possono cambiare rotta, divisione o rimozione delle scatole.",weightHeading:"Quando la prova d’imballaggio è utile",weightText:"Le pagine ufficiali mostrano attualmente 20 CNY e 3 USD per pacco. Verifica il checkout; la prova fornisce misure più realistiche prima del pagamento finale senza cambiare formula o tariffa.¶Aiuta con più scatole, forme miste, limiti o rotte sensibili a pochi centimetri."}
} as const;
for(const lang of ["de","es","fr","it"] as const){const correction=rehearsalArticleCorrections[lang],warehouse=({de,es,fr,it}[lang])["joyagoo-warehouse-rehearsal-shipping-guide"],weight=({de,es,fr,it}[lang])["volumetric-weight-guide"];warehouse.quickFacts[1]=correction.fact;warehouse.rows[5]=[correction.warehouseHeading,correction.warehouseText];weight.rows[8]=[correction.weightHeading,correction.weightText];}

const translations:Partial<Record<Exclude<Lang,"en">,TranslationMap>>={de,es,fr,it};

const depthNotes:Record<Exclude<Lang,"en">,string[]>={
de:[
"Praxisprüfung für „{topic}“: Notiere zuerst, welche konkrete Entscheidung dieser Punkt beeinflusst. Halte danach Quelle, Datum, sichtbaren Status und den Betrag oder die Option im Live-System fest. Ein Screenshot allein reicht selten; ergänze Bestellnummer, Variante und Zeitpunkt. So bleibt später nachvollziehbar, ob eine Abweichung vom Verkäufer, vom Lager, von der Route oder von einer nachträglichen Messung stammt.",
"Trenne bei „{topic}“ konsequent vier Rollen: Verkäufer, Einkaufsagent, Lager und internationaler Transporteur. Jede Rolle kontrolliert andere Schritte und Fristen. Eine verspätete Verkäuferlieferung ist kein Trackingproblem, und eine Carrier-Nachmessung ist kein Produktfehler. Diese Zuordnung macht Supportanfragen kürzer und überprüfbarer, weil du die richtige Phase, den letzten bestätigten Status und die erwartete nächste Aktion nennen kannst.",
"Behandle veröffentlichte Hilfe zu „{topic}“ als belastbare Ausgangsbasis, aber nicht als eingefrorenes Angebot. Routen, Preise, Verkäuferbedingungen und Länderregeln können sich ändern. Prüfe deshalb kurz vor jeder Zahlung noch einmal den aktiven Checkout und speichere die dort sichtbare Regel. Wenn zwei offizielle Seiten unterschiedliche Zahlen zeigen, dokumentiere beide und verwende für die Entscheidung den aktuellen Zahlungsbildschirm.",
"Für eine Kostenentscheidung bei „{topic}“ sollten mindestens vier Zahlen getrennt bleiben: Warenpreis, chinesische Inlandsfracht, optionale Lager- oder Verpackungsdienste und internationale Fracht. Rücksendung, Steuer oder Versicherung gehören als mögliche Zusatzposten daneben. Erst diese Aufteilung zeigt, ob eine Änderung wirklich teuer ist oder nur einen Betrag von einer Phase in eine andere verschiebt.",
"Baue zu „{topic}“ eine kleine Zeitleiste statt einer allgemeinen Erinnerung. Erfasse Verkäuferkauf, Versand in China, Lagereingang, QC Completed, eigene Entscheidung, Paketabgabe und internationale Übergaben. Fristen beginnen nicht alle am Bestelldatum. Mit genauen Zeitstempeln lässt sich erkennen, ob noch gehandelt werden kann und welche Verzögerung für den aktuellen Status tatsächlich ungewöhnlich ist.",
"Wenn Maße oder Gewicht bei „{topic}“ eine Rolle spielen, arbeite mit dem fertig verpackten Zustand. Produktgewicht, Verkaufskarton, Füllung, Verstärkung und Außenkarton sind unterschiedliche Bestandteile. Speichere Schätzung und Endmessung getrennt und notiere den verwendeten Divisor sowie Rundungsregeln. Eine belastbare Reklamation vergleicht dieselben Einheiten und dieselbe Verpackung, nicht zwei Werte aus verschiedenen Phasen.",
"Prüfe „{topic}“ immer gegen das Zielland und die tatsächlich sichtbare Route. Ein Produktlink beweist weder Versandfähigkeit noch Zollfreigabe. Produktart, Batterie, Flüssigkeit, Marke, Paketmaß und Empfängerland können Linien entfernen oder Bedingungen ändern. Die richtige Reihenfolge lautet daher: Ware identifizieren, Paketdaten klären, aktuelle Route öffnen und erst dann Preis, Versicherung und Laufzeit vergleichen.",
"Verkäuferbedingungen bleiben bei „{topic}“ ein eigener Risikofaktor. Sichere vor dem Kauf Bilder, Optionstext, Maße, Zubehör, Preis und Rückgabehinweise. Nach dem Lagereingang vergleichst du genau diesen Datensatz mit den QC-Fotos. Dadurch wird aus einem vagen Eindruck eine überprüfbare Abweichung, etwa falsche Größe, fehlendes Zubehör, sichtbarer Schaden oder eine andere ausgewählte Variante.",
"Vor dem nächsten Zahlungsschritt zu „{topic}“ sollte ein kurzer Abschlusscheck stehen: richtige Ware, richtige Option, offene QC-Frage, verbleibende Frist, gewünschte Verpackung, Zieladresse und aktuelle Kosten. Markiere außerdem, welcher Wert noch geschätzt ist. Diese eine Minute verhindert, dass ein vorläufiges Gewicht, ein alter Coupon oder eine frühere Verkäuferseite wie eine endgültige Zusage behandelt wird.",
"Falls bei „{topic}“ Support nötig wird, formuliere beobachtbare Fakten statt Bewertungen. Nenne Bestellung oder Paket, Status, Datum, ausgewählte Variante, erwarteten Zustand und sichtbare Abweichung. Füge genau das Bild oder Dokument bei, das die Aussage belegt, und schreibe die gewünschte Lösung dazu. Eine solche Anfrage lässt sich schneller an Verkäufer, Lager oder Logistik weitergeben als eine allgemeine Beschwerde.",
"Berücksichtige bei „{topic}“ auch den Moment nach der Zustellung. Außenkarton, Versandlabel, Innenpolsterung und Produkt sollten fotografiert werden, bevor Verpackung entsorgt wird. Bei sichtbarem Schaden ist die Dokumentation mit dem Zusteller besonders wichtig. Diese Belege zeigen, ob das Problem bereits beim Lagerfoto erkennbar war, durch Verpackung entstand oder während des internationalen Transports auftrat.",
"Für einen ersten Test von „{topic}“ ist eine kleine, gut dokumentierte Bestellung aussagekräftiger als ein großer Warenkorb. Wähle einen klar beschriebenen Artikel, speichere jeden Status und vergleiche Schätzung, QC, Verpackung und Endkosten. Das Ergebnis gilt nicht automatisch für jedes Land oder jede Route, liefert dir aber echte eigene Daten für die nächste Entscheidung statt nur fremde Einzelberichte.",
"Die Schlussregel für „{topic}“ lautet: Eine Zahl ohne Quelle, Datum und Status ist nur ein Hinweis. Verbinde jede wichtige Behauptung mit offizieller Regel, Live-Anzeige oder konkretem Beleg. Trenne garantierte Bedingungen von Schätzungen und Nutzererfahrungen. So bleibt der Leitfaden nützlich, selbst wenn sich Preise oder Routen ändern, und der Käufer weiß genau, was vor der Zahlung erneut geprüft werden muss."
],
es:[
"Comprobación práctica de «{topic}»: empieza por anotar qué decisión concreta depende de este punto. Guarda después la fuente, la fecha, el estado visible y el importe u opción que muestra la plataforma activa. Una captura aislada suele ser insuficiente; añade pedido, variante y hora. Así podrás distinguir si una diferencia procede del vendedor, del almacén, de la ruta o de una medición posterior.",
"Para «{topic}», separa siempre cuatro responsabilidades: vendedor, agente de compra, almacén y transportista internacional. Cada parte controla fases y plazos distintos. Un vendedor que tarda en enviar no es un problema de tracking internacional, y una nueva medición del transportista no es un defecto del producto. Esta separación permite indicar al soporte la fase exacta, el último estado confirmado y la acción esperada.",
"Usa la ayuda publicada sobre «{topic}» como base verificable, no como oferta congelada. Las rutas, precios, condiciones del vendedor y normas del país pueden cambiar. Revisa el checkout inmediatamente antes de pagar y conserva la regla que aparece allí. Si dos páginas oficiales muestran cifras diferentes, registra ambas y toma como referencia operativa el importe activo, sin ocultar la discrepancia al lector.",
"Para valorar el coste de «{topic}», mantén separados al menos cuatro importes: producto, entrega nacional en China, servicios opcionales de almacén o embalaje y transporte internacional. Añade devolución, impuestos y seguro como posibles costes distintos. Solo esta división permite saber si una modificación encarece realmente el pedido o simplemente traslada un pago de una fase a otra.",
"Crea una línea temporal para «{topic}» en lugar de una nota genérica. Registra compra al vendedor, salida en China, llegada al almacén, QC Completed, decisión del comprador, envío del paquete y transferencias internacionales. Los plazos no empiezan todos el día del pedido. Con horas y fechas concretas puedes saber si todavía es posible actuar y si la espera actual es realmente anormal.",
"Cuando «{topic}» dependa de medidas o peso, trabaja con el paquete terminado. Producto, caja comercial, relleno, refuerzo y cartón exterior son componentes diferentes. Guarda por separado la estimación y la medición final, además del divisor y el redondeo aplicados. Una reclamación sólida compara las mismas unidades y el mismo embalaje, no cifras tomadas de fases distintas.",
"Contrasta «{topic}» con el país de destino y la ruta que aparece en ese momento. Un enlace de producto no demuestra que el artículo pueda enviarse ni que pase aduanas. Tipo de mercancía, batería, líquido, marca, dimensiones y destino pueden eliminar líneas. Primero identifica el artículo y el paquete; después abre las rutas activas y compara precio, cobertura y condiciones.",
"Las reglas del vendedor siguen siendo un riesgo independiente en «{topic}». Antes de comprar, guarda imágenes, opción, medidas, accesorios, precio y condiciones de devolución. Al llegar al almacén, compara ese registro con las fotos de control. Así una impresión vaga se convierte en una diferencia comprobable: talla incorrecta, accesorio ausente, daño visible o variante distinta de la elegida.",
"Antes del siguiente pago relacionado con «{topic}», realiza un cierre breve: artículo correcto, variante, preguntas de control pendientes, plazo restante, embalaje solicitado, dirección y coste actual. Marca también qué cifra sigue siendo una estimación. Este minuto evita tratar un peso provisional, un cupón antiguo o una ficha modificada como si fueran compromisos definitivos.",
"Si necesitas soporte sobre «{topic}», describe hechos observables. Incluye número de pedido o paquete, estado, fecha, variante elegida, resultado esperado y diferencia visible. Adjunta únicamente la imagen o documento que demuestre esa afirmación y especifica la solución solicitada. Una petición así puede dirigirse al vendedor, almacén o transportista mucho mejor que una queja general sin contexto.",
"Incluye también la fase posterior a la entrega en «{topic}». Fotografía caja exterior, etiqueta, protección interior y producto antes de desechar el embalaje. Si el daño es visible, documentarlo con el repartidor aporta una prueba adicional. Este conjunto permite comparar el estado del control de almacén con el recibido y ayuda a localizar en qué fase pudo aparecer el problema.",
"Para probar «{topic}», un pedido pequeño y bien documentado enseña más que un carrito grande. Elige un artículo claramente descrito, guarda cada estado y compara estimación, control, embalaje y coste final. El resultado no garantiza la misma experiencia en todos los países o rutas, pero ofrece datos propios para la siguiente compra en lugar de depender únicamente de opiniones ajenas.",
"La regla final para «{topic}» es sencilla: una cifra sin fuente, fecha y estado es solo una señal. Relaciona cada afirmación importante con una norma oficial, pantalla activa o prueba concreta. Separa condiciones publicadas, estimaciones y experiencias de usuarios. Así el contenido sigue siendo útil cuando cambien rutas o precios y el comprador sabe qué debe confirmar otra vez antes de pagar."
],
fr:[
"Contrôle pratique de « {topic} » : commencez par noter la décision précise qui dépend de ce point. Conservez ensuite la source, la date, le statut visible et le montant ou l’option affichés sur la plateforme active. Une capture seule suffit rarement ; ajoutez commande, variante et heure. Vous pourrez ainsi distinguer un écart venant du vendeur, de l’entrepôt, de la ligne ou d’une nouvelle mesure.",
"Pour « {topic} », séparez quatre responsabilités : vendeur, agent d’achat, entrepôt et transporteur international. Chacun contrôle des étapes et délais différents. Un vendeur lent n’est pas un problème de suivi international, et une nouvelle mesure du transporteur n’est pas un défaut produit. Cette distinction permet d’indiquer au support la phase exacte, le dernier statut confirmé et l’action attendue.",
"Considérez l’aide publiée sur « {topic} » comme une base vérifiable, pas comme une offre figée. Lignes, prix, règles vendeur et exigences nationales peuvent évoluer. Vérifiez le paiement juste avant de régler et conservez la règle affichée. Si deux pages officielles donnent des chiffres différents, documentez les deux et utilisez le montant actif pour la décision sans cacher l’écart au lecteur.",
"Pour évaluer le coût de « {topic} », séparez au moins quatre montants : produit, livraison intérieure chinoise, services optionnels d’entrepôt ou d’emballage et fret international. Ajoutez retour, taxes et assurance comme postes possibles distincts. Cette ventilation montre si une modification augmente réellement le total ou déplace simplement un paiement d’une étape vers une autre.",
"Construisez une chronologie pour « {topic} » plutôt qu’un rappel général. Notez achat vendeur, expédition chinoise, arrivée à l’entrepôt, QC Completed, décision, soumission du colis et transferts internationaux. Tous les délais ne commencent pas le jour de la commande. Avec des dates précises, vous savez si une action reste possible et si l’attente actuelle est réellement anormale.",
"Quand « {topic} » dépend des dimensions ou du poids, raisonnez sur le colis terminé. Produit, boîte commerciale, rembourrage, renfort et carton extérieur sont différents. Conservez séparément estimation et mesure finale, avec diviseur et règle d’arrondi. Une réclamation solide compare les mêmes unités et le même emballage, pas deux chiffres provenant d’étapes différentes.",
"Vérifiez « {topic} » selon le pays de destination et la ligne réellement visible. Un lien produit ne prouve ni l’expédiabilité ni le dédouanement. Type de marchandise, batterie, liquide, marque, dimensions et destination peuvent supprimer des lignes. Identifiez d’abord le produit et le colis, puis ouvrez les options actives avant de comparer prix, couverture et conditions.",
"Les conditions du vendeur restent un risque séparé pour « {topic} ». Avant l’achat, conservez images, option, mesures, accessoires, prix et retour. À l’arrivée, comparez ce dossier aux photos QC. Une impression vague devient alors un écart vérifiable : mauvaise taille, accessoire absent, dommage visible ou variante différente de celle enregistrée.",
"Avant le paiement suivant lié à « {topic} », faites un contrôle final : bon article, bonne variante, question QC ouverte, délai restant, emballage demandé, adresse et coût actuel. Marquez aussi chaque valeur encore estimée. Cette minute évite de traiter un poids provisoire, un ancien coupon ou une fiche modifiée comme un engagement définitif.",
"Si le support est nécessaire pour « {topic} », décrivez des faits observables. Indiquez commande ou colis, statut, date, variante choisie, résultat attendu et écart visible. Joignez seulement l’image ou le document qui prouve ce point et précisez la solution souhaitée. Une demande structurée peut être transmise au bon responsable bien plus vite qu’une plainte générale.",
"Incluez l’étape après livraison dans « {topic} ». Photographiez carton extérieur, étiquette, protection intérieure et produit avant de jeter l’emballage. Si le dommage est visible, une constatation avec le livreur renforce le dossier. Ces éléments permettent de comparer l’état montré au contrôle avec l’état reçu et d’identifier la phase où le problème a pu apparaître.",
"Pour tester « {topic} », une petite commande bien documentée est plus instructive qu’un grand panier. Choisissez un article clairement décrit, conservez chaque statut et comparez estimation, QC, emballage et coût final. Le résultat ne garantit pas la même expérience dans tous les pays ou sur toutes les lignes, mais il fournit des données personnelles utiles pour la décision suivante.",
"La règle finale pour « {topic} » : un chiffre sans source, date et statut n’est qu’un signal. Reliez chaque affirmation importante à une règle officielle, un écran actif ou une preuve concrète. Séparez conditions publiées, estimations et expériences d’utilisateurs. Le guide reste ainsi utile lorsque prix ou lignes changent et indique clairement ce qui doit être revérifié avant paiement."
],
it:[
"Verifica pratica di «{topic}»: annota prima quale decisione concreta dipende da questo punto. Conserva poi fonte, data, stato visibile e importo o opzione mostrati dalla piattaforma attiva. Uno screenshot isolato raramente basta; aggiungi ordine, variante e orario. In questo modo potrai capire se una differenza nasce dal venditore, dal magazzino, dalla rotta o da una misurazione successiva.",
"Per «{topic}», separa quattro responsabilità: venditore, agente d’acquisto, magazzino e vettore internazionale. Ognuno controlla fasi e tempi diversi. Un venditore lento non è un problema di tracking internazionale e una nuova misura del corriere non è un difetto del prodotto. Questa distinzione rende più chiaro indicare al supporto fase esatta, ultimo stato confermato e azione richiesta.",
"Usa la guida pubblicata su «{topic}» come base verificabile, non come offerta immutabile. Rotte, prezzi, condizioni del venditore e regole nazionali possono cambiare. Controlla il checkout subito prima del pagamento e salva la regola visibile. Se due pagine ufficiali mostrano cifre diverse, documentale entrambe e usa per la decisione il prezzo attivo senza nascondere la discrepanza.",
"Per valutare il costo di «{topic}», mantieni separati almeno quattro importi: prodotto, consegna interna in Cina, servizi opzionali di magazzino o imballaggio e trasporto internazionale. Aggiungi reso, imposte e assicurazione come possibili voci distinte. Solo questa divisione mostra se una modifica aumenta davvero il totale o sposta semplicemente un pagamento da una fase all’altra.",
"Crea una linea temporale per «{topic}» invece di un promemoria generico. Registra acquisto dal venditore, partenza in Cina, arrivo in magazzino, QC Completed, decisione, invio del pacco e trasferimenti internazionali. Le scadenze non iniziano tutte il giorno dell’ordine. Con date precise puoi capire se è ancora possibile agire e se l’attesa attuale è davvero anomala.",
"Quando «{topic}» dipende da misure o peso, ragiona sul pacco finito. Prodotto, scatola commerciale, riempimento, rinforzo e cartone esterno sono componenti diversi. Salva separatamente stima e misura finale, insieme a divisore e arrotondamento. Un reclamo solido confronta le stesse unità e lo stesso imballaggio, non valori presi in fasi differenti.",
"Controlla «{topic}» rispetto al paese di destinazione e alla rotta realmente visibile. Un link prodotto non dimostra che l’articolo sia spedibile o che superi la dogana. Tipo di merce, batteria, liquido, marchio, dimensioni e destinazione possono eliminare linee. Identifica prima articolo e pacco, poi apri le rotte attive e confronta prezzo, copertura e condizioni.",
"Le condizioni del venditore restano un rischio separato in «{topic}». Prima dell’acquisto salva immagini, opzione, misure, accessori, prezzo e regole di reso. All’arrivo confronta questo registro con le foto QC. Così un’impressione vaga diventa una differenza verificabile: taglia errata, accessorio mancante, danno visibile o variante diversa da quella selezionata.",
"Prima del pagamento successivo legato a «{topic}», fai un controllo finale: articolo corretto, variante, domanda QC aperta, tempo residuo, imballaggio richiesto, indirizzo e costo attuale. Segna anche quale valore è ancora stimato. Questo minuto evita di trattare un peso provvisorio, un vecchio coupon o una pagina modificata come impegno definitivo.",
"Se serve supporto per «{topic}», descrivi fatti osservabili. Indica ordine o pacco, stato, data, variante scelta, risultato atteso e differenza visibile. Allega solo l’immagine o il documento che dimostra quel punto e specifica la soluzione desiderata. Una richiesta strutturata può essere inviata al responsabile corretto molto più facilmente di un reclamo generale senza contesto.",
"Includi anche la fase dopo la consegna in «{topic}». Fotografa cartone esterno, etichetta, protezione interna e prodotto prima di eliminare l’imballo. Se il danno è visibile, documentarlo con il corriere rafforza la prova. Questi elementi consentono di confrontare lo stato mostrato dal magazzino con quello ricevuto e individuare quando il problema può essere comparso.",
"Per provare «{topic}», un ordine piccolo e ben documentato insegna più di un carrello grande. Scegli un articolo descritto chiaramente, salva ogni stato e confronta stima, QC, imballo e costo finale. Il risultato non garantisce la stessa esperienza in tutti i paesi o rotte, ma fornisce dati personali utili per la decisione successiva invece di sole recensioni altrui.",
"La regola finale per «{topic}» è semplice: una cifra senza fonte, data e stato è solo un segnale. Collega ogni affermazione importante a una regola ufficiale, una schermata attiva o una prova concreta. Separa condizioni pubblicate, stime ed esperienze degli utenti. Così la guida resta utile quando cambiano prezzi o rotte e mostra cosa va ricontrollato prima di pagare."
]};

const depthBridges:Record<Exclude<Lang,"en">,string[]>={
de:[
"Übertrage diesen Punkt anschließend in eine einfache Entscheidungstabelle mit den Spalten bestätigt, geschätzt, offen und Frist. Bestätigt wird nur, was offizielle Hilfe oder Live-System konkret zeigt; geschätzt bleiben Gewicht, Laufzeit und vorläufige Fracht. Unter offen stehen fehlende Fotos oder Verkäuferantworten. Diese Trennung verhindert, dass eine Vermutung unbemerkt zur angeblichen Plattformregel wird.",
"Vergleiche außerdem nicht nur den günstigsten sichtbaren Wert. Schreibe daneben, welche Leistung, Verpackung, Haftung, Länderregel und Messmethode enthalten ist. Zwei Routen oder Verkäuferangebote können ähnlich aussehen und trotzdem unterschiedliche Risiken übertragen. Eine gute Entscheidung erklärt deshalb nicht nur, was weniger kostet, sondern auch, welche Annahme dahintersteht und was bei einer Abweichung noch geändert werden kann.",
"Für spätere Aktualisierungen sollte jede wichtige Aussage einen Wartungspunkt erhalten: offizielle Quellseite, zuletzt geprüftes Datum und die Stelle im Käuferprozess, an der eine Live-Prüfung nötig ist. Dadurch kann ein geänderter Preis korrigiert werden, ohne den ganzen Artikel neu zu schreiben. Gleichzeitig erkennt der Leser sofort, welche Information dauerhaft und welche bewusst zeitabhängig formuliert ist.",
"Nutze diesen Abschnitt schließlich als Handlungsschritt, nicht nur als Erklärung. Formuliere eine konkrete nächste Aktion, den benötigten Beleg und eine klare Abbruchbedingung. Wenn die Variante nicht bestätigt, die Frist abgelaufen oder die Route für das Produkt nicht sichtbar ist, sollte der Käufer pausieren. Dieses Vorgehen schützt besser als eine allgemeine Empfehlung, vorsichtig zu sein."
],
es:[
"Pasa este punto a una tabla de decisión con cuatro columnas: confirmado, estimado, pendiente y plazo. Solo debe figurar como confirmado lo que muestre la ayuda oficial o la plataforma activa; peso, duración y flete inicial siguen siendo estimaciones. En pendiente quedan fotos o respuestas faltantes. Esta separación evita que una suposición termine presentada como una norma real del servicio.",
"No compares únicamente la cifra más barata. Anota al lado qué servicio, embalaje, cobertura, regla nacional y método de medición incluye. Dos rutas o anuncios pueden parecer equivalentes y trasladar riesgos muy distintos al comprador. Una decisión útil explica por qué cuesta menos, qué hipótesis utiliza y qué elementos todavía pueden cambiarse antes de cerrar el pago.",
"Para futuras actualizaciones, cada afirmación importante necesita una referencia de mantenimiento: página oficial, fecha de última comprobación y fase en la que debe revisarse el dato activo. Así un cambio de precio puede corregirse sin rehacer el artículo entero. El lector también distingue mejor entre una regla estable y un dato que depende conscientemente del momento de consulta.",
"Convierte finalmente esta sección en una acción concreta: define el siguiente paso, la prueba necesaria y una condición clara para detenerse. Si la variante no está confirmada, el plazo terminó o la ruta no aparece para ese producto, el comprador debe pausar la operación. Este criterio protege mucho más que una recomendación vaga de tener cuidado."
],
fr:[
"Reportez ensuite ce point dans un tableau de décision à quatre colonnes : confirmé, estimé, en attente et échéance. Seuls l’aide officielle ou l’écran actif permettent de confirmer une donnée ; poids, délai et fret initial restent des estimations. Placez les photos ou réponses manquantes en attente. Cette séparation empêche une hypothèse de devenir par erreur une prétendue règle de la plateforme.",
"Ne comparez pas seulement le chiffre le plus bas. Notez le service, l’emballage, la couverture, la règle nationale et la méthode de mesure inclus. Deux lignes ou annonces peuvent sembler équivalentes tout en transférant des risques différents à l’acheteur. Une décision utile explique donc le prix, les hypothèses utilisées et ce qui peut encore être modifié avant le paiement final.",
"Pour les mises à jour futures, associez à chaque affirmation importante une page officielle, une date de vérification et l’étape où le contrôle en direct reste nécessaire. Un prix modifié pourra ainsi être corrigé sans réécrire tout l’article. Le lecteur distingue également une règle relativement stable d’une donnée volontairement dépendante du moment de consultation.",
"Transformez enfin cette section en action : définissez l’étape suivante, la preuve nécessaire et une condition d’arrêt claire. Si la variante n’est pas confirmée, si le délai est dépassé ou si aucune ligne n’apparaît pour le produit, l’acheteur doit faire une pause. Ce critère protège davantage qu’un simple conseil général de prudence."
],
it:[
"Trasferisci poi questo punto in una tabella decisionale con quattro colonne: confermato, stimato, aperto e scadenza. È confermato solo ciò che mostrano la guida ufficiale o la piattaforma attiva; peso, durata e trasporto iniziale restano stime. Tra gli elementi aperti inserisci foto o risposte mancanti. Questa separazione impedisce che un’ipotesi venga presentata per errore come regola reale del servizio.",
"Non confrontare soltanto il valore più basso. Annota servizio, imballaggio, copertura, regola nazionale e metodo di misura inclusi. Due rotte o inserzioni possono sembrare equivalenti e trasferire rischi molto diversi al compratore. Una decisione utile spiega quindi perché costa meno, quali ipotesi usa e cosa può ancora essere modificato prima del pagamento finale.",
"Per gli aggiornamenti futuri, collega ogni affermazione importante a una pagina ufficiale, una data di verifica e la fase in cui serve un controllo dal vivo. Così un prezzo cambiato può essere corretto senza riscrivere l’intero articolo. Il lettore distingue anche una regola relativamente stabile da un dato che dipende consapevolmente dal momento della consultazione.",
"Trasforma infine questa sezione in un’azione: definisci il passo successivo, la prova necessaria e una condizione chiara per fermarsi. Se la variante non è confermata, la scadenza è passata o la rotta non appare per quel prodotto, il compratore deve sospendere. Questo criterio protegge più di un consiglio generico a fare attenzione."
]};

export function getLocalizedSeoArticle(slug:string,lang:Lang):SeoArticle|undefined{
  const base=getSeoArticle(slug);if(!base||lang==="en")return base;
  if(slug===returnMatrixArticle.slug)return returnMatrixTranslations[lang]??base;
  const translated=translations[lang]?.[slug];if(!translated)return base;
  const notes=depthNotes[lang];
  const bridges=depthBridges[lang];
  return {...base,title:translated.title,description:translated.description,meta:translated.meta,sourceNote:translated.sourceNote,quickFacts:translated.quickFacts,sections:translated.rows.map(([heading,text],index)=>({heading,paragraphs:[...text.split("¶"),notes[index%notes.length].replace("{topic}",heading),...(index<bridges.length?[bridges[index]]:[])]}))};
}
const publishingOrder=["joyagoo-return-eligibility-matrix-seller-condition-packaging","joyagoo-fee-policy-free-agent-service-transaction-costs","joyagoo-buying-fees-guide","joyagoo-qc-return-window-guide","volumetric-weight-guide","joyagoo-warehouse-rehearsal-shipping-guide","joyagoo-reviews-buyer-signals"];
export function getLocalizedSeoArticles(lang:Lang){return publishingOrder.map(slug=>getLocalizedSeoArticle(slug,lang)).filter((article):article is SeoArticle=>Boolean(article));}
